const n=[{id:"vb04-1",s:"",cc:"Điều lệ Đảng Cộng sản Việt Nam (Đại hội XI, 2011) — Phân mở đâu: “Đảng Cộng sản Việt Nam do đồng chí Hồ Chí Minh sáng lập và rèn luyện...”",gt:"Chủ tịch Hồ Chí Minh là người sáng lập và rèn luyện Đảng Cộng sản Việt Nam, đặt nền móng cho cách mạng Việt Nam hiện đại.",mn:"Người sáng lập và rèn luyện Đảng chỉ có một: Bác Hồ (Hồ Chí Minh). Loại ngay các Tổng Bí thư, Thủ tướng.",t:"m",q:"Đảng Cộng sản Việt Nam do ai sáng lập và rèn luyện?",o:["Chủ tịch Tôn Đức Thắng","Chủ tịch Hồ Chí Minh","Tổng Bí thư Trường Chính","Thủ tướng Phạm Vận Động"],c:1},{id:"vb04-2",s:"",cc:"Điều lệ Đảng Cộng sản Việt Nam (Đại hội XI, 2011) - Mục “Đảng và những vấn đề cơ bản về xây dựng Đảng.",gt:"Điều lệ xác định Đảng là đội tiên phong của giai cấp công nhân, đồng thời là đội tiên phong của nhân dân lao động và dân tộc Việt Nam, thể hiện vai trò đại diện cho lợi ích chung của toàn dân tộc.",mn:'Nhớ bộ ba "công nhân - lao động - dân tộc": đội tiên phong của giai cấp công nhân, nhân dân lao động VÀ cả dân tộc Việt Nam.',t:"m",q:"Đảng Cộng sản Việt Nam là đội tiên phong của lực lượng nào dưới đây?",o:["Giai cấp công nhân và nông dân Việt Nam","Giai cấp công nhân, nhân dân lao động và dân tộc Việt Nam","Nhân dân lao động và trí thức Việt Nam","Toàn thể nhân dân Việt Nam"],c:1},{id:"vb04-3",s:"",cc:"Điều lệ Đảng (Đại hội XI, 2011) ~ Phần “Mục đích của Đảng”.",gt:"Mục đích của Đảng là xây dựng nước Việt Nam độc lập, dân chủ, giàu mạnh, xã hội công bằng, văn minh, tiến tới chủ nghĩa cộng sản.",mn:'Dích cao nhất - cuối cùng là chủ nghĩa cộng sản. Cư thấy “cuối cùng" thì chọn cộng sản (đáp án C).',t:"m",q:"Mục đích cao nhất của Đảng Cộng sản Việt Nam là gì?",o:["Xây dựng nước Việt Nam dân chủ, công bằng, văn minh","Xây dựng xã hội chủ nghĩa","Thực hiện thành công chủ nghĩa xã hội và cuối cùng là chủ nghĩa cộng sản","Làm cho dân giàu, nước mạnh, xã hội hạnh phúc"],c:2},{id:"vb04-4",s:"",cc:"Điều lệ Đảng (Đại hội XI, 2011) ~ Phần “Nền tảng tư tưởng ”.",gt:"Đảng khẳng định chủ nghĩa Mác - Lênin và tư tưởng Hồ Chí Minh là nền tảng tư tưởng, kim chỉ nam cho hành động, giúp định hướng mọi hoạt động cách mạng.",mn:"Nền tảng tư tưởng = cấp đối Mác - Lênin + tư tưởng Hồ Chí Minh. Phải đủ CẢ HAI mới dụng (A).",t:"m",q:"Đảng lấy nền tảng tư tưởng nào làm kim chỉ nam cho hành động?",o:["Chủ nghĩa Mác - Lênin và tư tưởng Hồ Chí Minh","Chủ nghĩa xã hội khoa học","Tư tưởng Hồ Chí Minh","Chủ nghĩa Mác - Lênin"],c:0},{id:"vb04-5",s:"",cc:"Điều lệ Đảng (Đại hội XI, 2011) ~= Phần “Nguyên tắc tổ chức”.",gt:"Đảng là một tổ chức chặt chẽ, thống nhất ý chí và hành động, lấy tập trung dân chủ làm nguyên tắc tổ chức cơ bản.",mn:'Nguyên tắc cơ bản là TẬP TRUNG dân chủ (tập trung dụng trước), không phải "dân chủ tập trung” đảo ngược.',t:"m",q:"Nguyên tắc tổ chức cơ bản của Đảng Cộng sản Việt Nam là gì?",o:["Dân chủ tập trung","Tập trung dân chủ","Tập thể lãnh đạo, cá nhân phụ trách","Phê bình và tự phê bình"],c:1},{id:"vb04-6",s:"",cc:"Điều lệ Đảng (Đại hội XI, 2011) ~ Phần “Đang là đội tiên phong...”.",gt:"Điều lệ nêu rõ Đảng đồng thời là đội tiên phong của giai cấp công nhân, nhân dân lao động và dân tộc Việt Nam, thể hiện vai trò lãnh đạo toàn dân tộc.",mn:'Chữ "vừa... vừa...”: vừa tiền phong của công nhân, vừa của nhân dân lao động và dân tộc — chọn ý đây đủ nhất (B).',t:"m",q:"Khẳng định nào sau đây là đúng về vai trò của Đảng Cộng sản Việt Nam?",o:["Đảng chỉ đại diện cho lợi ích của giai cấp công nhân.","Đảng vừa là đội tiên phong của giai cấp công nhân, vừa là đội tiên phong của nhân dân lao động và dân tộc Việt Nam.","Đảng chỉ đại diện cho lợi ích của nhân dân lao động.","Đảng là tổ chức chính trị của toàn thể nhân dân Việt Nam."],c:1},{id:"vb04-7",s:"",cc:"Điều lệ Đảng (Đại hội XI, 2011) — Đoạn: “Đảng Cộng sản Việt Nam là đảng cầm quyền...”.",gt:"Đảng được xác định là đảng cầm quyền, lãnh đạo hệ thống chính trị, đồng thời chịu sự giám sát của nhân dân.",mn:'Đảng cầm quyền thì mỗi “chịu sự giám sát của nhân dân". Ghép "cầm quyền — giám sát" là ra B.',t:"m",q:"Điền tự còn thiếu vào chỗ trọng: “Đảng Cộng sản Việt Nam là đảng tôn trọng và phát huy quyền làm chủ của nhân dân, chịu sự giám sát của nhân dân.”",o:["tiên phong","cầm quyền","cách mạng","chính trị"],c:1},{id:"vb04-8",s:"",cc:"Điều lệ Đảng (Đại hội XI, 2011) - Mục “Dũng lãnh đạo hệ thống chính trừ..”.",gt:"Đảng không phải là tổ chức đối lập với Nhà nước mà là lực lượng lãnh đạo Nhà nước và hệ thống chính trị.",mn:'Câu SAI là câu "Đáng đối lập với Nhà nước" (C) - thực tế Đảng LÃNH ĐẠO Nhà nước, không đối lập.',t:"m",q:"Khẳng định nào sau đây là sai theo Điều lệ Đảng Cộng sản Việt Nam?",o:["Đảng hoạt động trong khuôn khổ Hiến pháp và pháp luật.","Đảng là tổ chức thống nhất ý chí và hành động.","Đảng là tổ chức đối lập với Nhà nước.","Đang thực hiện nguyên tắc tự phê bình và phê bình."],c:2},{id:"vb04-9",s:"",cc:"Điều lệ Đảng (Đại hội XI, 2011) - Phần “Đảng là đội tiên phong...”.",gt:"Điều lệ quy định Đảng là đội tiên phong của giai cấp công nhân, đồng thời là đội tiên phong của nhân dân lao động và dân tộc Việt Nam ~- không tách rời giai cấp công nhân.",mn:"Nhận định bổ giai cấp công nhân là SAI - Đảng không bao giờ tách rời giai cấp công nhân. Chọn B (Sai).",t:"m",q:"Nhận định sau đây đúng hay sai? “Đảng Cộng sản Việt Nam là đội tiên phong của nhân dân lao động và dân tộc Việt Nam, không bao gồm giai cấp công nhân.”",o:["Đúng","Sai"],c:1},{id:"vb04-10",s:"",cc:"Điều lệ Đảng (Đại hội XI, 2011) — Phần “Nguyên tắc tổ chức”.",gt:"Đảng hoạt động theo nguyên tắc tập trung dân chủ, thực hiện tập thể lãnh đạo, cá nhân phụ trách, đề cao kỷ luật và đoàn kết nội bộ.",mn:'Dụng phải là "tập thể lãnh đạo, cá nhân phụ trách" + tập trung dân chủ (B). Đạo thành "cá nhân lãnh đạo” là sai. Chương I: ĐỘNG VIÊN',t:"m",q:"Theo Điều lệ Đảng, khẳng định nào sau đây thể hiện đúng nguyên tắc sinh hoạt, tổ chức của Đảng?",o:["Mọi đảng viên đều được quyền quyết định độc lập khi triển khai công việc.","Tập thể lãnh đạo, cá nhân phụ trách, lấy tập trung dân chủ làm nguyên tắc cơ bản.","Cá nhân lãnh đạo, tập thể chịu trách nhiệm.","Đảng không thực hiện tự phê bình và phê bình. lược nghiệm Điều lọ Dáng - Trang ¬"],c:1},{id:"vb04-11",s:"",cc:"Điều 4, khoản 1 = Điều lệ Đảng Cộng sản Việt Nam (Đại hội X1, 2011).",gt:"Người vào Đảng phải được hai đảng viên chính thức giới thiệu theo quy định.",mn:'Vào Đảng cần 2 đảng viên chính thức giới thiệu - nhớ "đối bạn cùng tiến”, một mình không đủ.',t:"m",q:"Người vào Đảng phải có bao nhiêu đảng viên chính thức giới thiệu?",o:["1","2","3","4"],c:1},{id:"vb04-12",s:"",cc:"liệu 4, khoản 2 — Điều lệ Đảng.",gt:"Người giới thiệu phải là đảng viên chính thức và cùng công tác với người vào Đảng ít nhất một năm.",mn:"Người giới thiệu phải cùng công tác ít nhất 1 năm - đủ một vòng năm mới hiểu rõ nhau.",t:"m",q:"Người giới thiệu kết nạp phải cùng công tác với người vào Đảng ít nhất bao lâu?",o:["6 tháng","1năm","2năm","3năm"],c:1},{id:"vb04-13",s:"",cc:"Điều 5, khoản 1 — Điều lệ Đảng.",gt:"Người được kết nạp vào Đảng phải trải qua thời kỳ dự bị 12 tháng, tính từ ngày chỉ bộ tổ chức lễ kết nạp.",mn:"Dự bị đúng 12 tháng - trọn một năm thử thách, tính từ ngày lễ kết nạp.",t:"m",q:"Thời gian dự bị của người được kết nạp vào Đảng là bao lâu?",o:["6 tháng","9 tháng","12 tháng","24 tháng"],c:2},{id:"vb04-14",s:"",cc:"Diệu #, khoản 1 - Điều lệ Đảng.",gt:"Trường hợp đảng viên bỏ sinh hoạt chỉ bộ hoặc không đóng đảng phí 3 tháng mà không có lý do chính đáng, chỉ bộ xem xét, đề nghị cấp có thẩm quyền xoá tên khỏi danh sách đảng viên.",mn:"Bỏ sinh hoạt/không đóng đảng phí 3 tháng vô cơ, xem xét, đề nghị xoá tên (không phải kỷ luật).",t:"m",q:"Đảng viên bỏ sinh hoạt chỉ bộ hoặc không đóng đảng phí 3 tháng trong năm mà không có lý do chính đáng sẽ bị xử lý thế nào?",o:["Khiển trách","Cảnh cáo","Xem xét, đề nghị xoá tên khỏi danh sách đảng viên","Đình chỉ sinh hoạt"],c:2},{id:"vb04-15",s:"",cc:"Điều 6 — Điều lệ Đảng.",gt:"Ban Chấp hành Trung ương là cơ quan quy định việc phát và quản lý thẻ đảng viên, hồ sơ đảng viên và thủ tục chuyển sinh hoạt đảng.",mn:"Thẻ đảng viên do Ban Chấp hành Trung ương quy định phát và quản lý - việc lớn thuộc cấp cao nhất. lược nghiệm Điều lọ Dáng Trang ~",t:"m",q:"Ai có thẩm quyền quy định việc phát và quản lý thẻ đảng viên?",o:["Chỉ bộ","Đảng uỷ cơ sở","Ban Chấp hành Trung ương","Cấp uỷ tỉnh, thành"],c:2},{id:"vb04-16",s:"",cc:"Điều 5, khoản 3 — Điều lệ Đảng Cộng sản Việt Nam (Đại hội XI, 2011).",gt:"Sau khi chỉ bộ biểu quyết công nhận đảng viên chính thức, cấp uỷ có thẩm quyền quyết định việc công nhận này.",mn:"Chi bộ biểu quyết, nhưng cấp uỷ có thẩm quyền mời quyết định công nhận chính thức.",t:"m",q:"Khi hết thời kỳ dự bị, việc công nhận đảng viên chính thức do ai quyết định?",o:["Chi bộ nội sinh hoạt","Cấp uỷ có thẩm quyền","Ban Thường vụ cấp trên trực tiếp","Ban Chấp hành Trung ương"],c:1},{id:"vb04-17",s:"",cc:"Điều 5, khoản 4 — Điều lệ Đảng.",gt:"Tuổi đảng của đảng viên được tính từ ngày ghi trong quyết định kết nạp.",mn:"Tuổi đảng tính từ ngày ghi trong quyết định kết nạp - lấy mốc trên giấy, không phải ngày dự lề.",t:"m",q:"Tuổi đảng của đảng viên được tính từ thời điểm nào?",o:["Ngày vào sinh hoạt chi bộ đầu tiên","Ngày được công nhận đảng viên chính thức","Ngày ghi trong quyết định kết nạp","Ngày dự lễ kết nạp"],c:2},{id:"vb04-18",s:"",cc:"Điều 7 ~= Điều lệ Đảng.",gt:"Chi bộ xem xét, quyết định việc giám hoặc miễn công tác, sinh hoạt đảng cho đảng viên tuổi cao, sức yếu.",mn:"Đảng viên tuổi cao, sức yếu xin giảm sinh hoạt ¬ chi bộ xem xét, quyết định (gần dân, gắn đảng viên nhất).",t:"m",q:"Trường hợp đảng viên tuổi cao, sức yếu, xin giảm công tác và sinh hoạt đảng thì ai xem xét quyết định?",o:["Cấp uỷ cấp trên trực tiếp","Chi bộ nội sinh hoạt","Ban Thường vụ cấp tỉnh","Cấp uỷ cơ sở"],c:1},{id:"vb04-19",s:"",cc:"Điều 4, khoản 4 -— Điều lệ Động.",gt:"Cấp uỷ cấp trên trực tiếp có thể cử đảng viên về làm công tác tuyên truyền, xem xét, giới thiệu người kết nạp vào Đảng.",mn:"Nơi chưa có đảng viên. - cấp uỷ cấp trên trực tiếp cử người về tuyên truyền, giới thiệu kết nạp.",t:"m",q:"Trường hợp chưa có đảng viên hoặc chưa đủ điều kiện giới thiệu người vào Đảng, thì ai có trách nhiệm cử đảng viên về tuyên truyền, giới thiệu kết nạp?",o:["Đảng uỷ cơ sở","Chi uỷ nơi do","Cấp uỷ cấp trên trực tiếp","Ban Tổ chức Trung ương"],c:2},{id:"vb04-20",s:"",cc:"Điều #, khoản Ì- Điều lệ Đảng,",gt:"Đảng viên giảm sút ý chí phấn đấu, không làm nhiệm vụ đảng viên, đã được chỉ bộ giáo dục mà không tiến bộ, chỉ bộ xem xét, đề nghị xoá tên.",mn:"Xoá tên khi giảm sút ý chí, không làm nhiệm vụ, giáo dục mà không tiến bộ ~ lợi ở tinh thần phấn đấu.",t:"m",q:"Đảng viên có thể bị xoá tên trong danh sách đảng viên nếu thuộc trường hợp nào dưới đây?",o:["Không đóng đảng phí trong 1 tháng","Không tham gia công tác xã hội","Giảm sút ý chí phấn đấu, không làm nhiệm vụ đảng viên dự đã được giáo dục mà không tiến bộ","Không tham gia hợp cấp uỷ"],c:2},{id:"vb04-21",s:"",cc:"Điều 1, khoản 2 — Điều lệ Đảng.",gt:"Người vào Đảng phải tự nguyện thực hiện Cương lĩnh, Điều lệ, tiêu chuẩn, nhiệm vụ đảng viên và được nhân dân tín nhiệm.",mn:"Tiêu chuẩn: tự nguyện thực hiện Cương lĩnh, Điều lệ và được nhân dân tín nhiệm - không phải bằng cấp hay thâm niên.",t:"m",q:"Khẳng định nào sau đây là đúng về tiêu chuẩn của người được xem xét kết nạp vào Đảng?",o:["Chỉ cần có trình độ chuyên môn cao.","Tự nguyện thực hiện Cương lĩnh, Điều lệ Đảng và được nhân dân tín nhiệm.","Có công tác trong cơ quan nhà nước từ 3 năm trở lên.","Là đoàn viên công đoàn hoặc đoàn thanh niên đều được kết nạp không cần giới thiệu."],c:1},{id:"vb04-22",s:"",cc:"Điều 1, khoản 1 -— Điều lệ Đảng.",gt:"Đảng viên là chiến sĩ cách mạng trong đội tiên phong của giai cấp công nhân, nhân dân lao động và dân tộc Việt Nam.",mn:'Đảng viên là chiến sĩ cách mạng trong đội tiên phong - nhớ hình ảnh người lĩnh, không phải "người lãnh đạo”.',t:"m",q:"“Đảng viên Đảng Cộng sản Việt Nam là trong đội tiên phong của giai cấp công nhân, nhân dân lao động và dân tộc Việt Nam.”",o:["người lãnh đạo","chiến sĩ cách mạng","người tuyên truyền","cán bộ ưu tú"],c:1},{id:"vb04-23",s:"",cc:"Điều 3 và Điều 7 ~ Điều lệ Đảng.",gt:"Điều lệ không quy định đảng viên được tự ý miễn sinh hoạt đảng: việc này phải được chỉ bộ xem xét, quyết định.",mn:"Câu SAI: tự ý miễn sinh hoạt 6 tháng — miễn sinh hoạt phải do chi bộ quyết, không tự ý.",t:"m",q:"Khẳng định nào sau đây là sai về quyền của đảng viên?",o:["Được thông tin, thảo luận, biểu quyết công việc của Đảng.","Được ứng cử, đề cử, bầu cử cơ quan lãnh đạo của Đảng.","Được phê bình, chất vấn về hoạt động của tổ chức đảng.","Được miễn sinh hoạt đảng nếu có việc riêng trong 6 tháng."],c:3},{id:"vb04-24",s:"",cc:"Điều 4, khoản 2 — Điều lộ Đảng.",gt:"Người giới thiệu phải là đảng viên chính thức, cùng công tác ít nhất 1 năm, báo cáo và chịu trách nhiệm về việc giới thiệu.",mn:"Người giới thiệu phải báo cáo và chịu trách nhiệm về lý lịch, phẩm chất - không chỉ kỹ cho cơ.",t:"m",q:"Khẳng định nào sau đây là đúng về trách nhiệm của người giới thiệu vào Đảng?",o:["Chỉ cần ký xác nhận đơn xin vào Đảng.","Báo cáo với chi bộ về lý lịch, phẩm chất của người vào Đảng và chịu trách nhiệm về sự giới thiệu đó.","Không cần công tác cùng người được giới thiệu.","Chỉ cần là đảng viên dự bị."],c:1},{id:"vb04-25",s:"",cc:"Điều 5, khoản Ì - Điều lệ Đảng.",gt:"Thời kỳ dự bị cơ định là 12 tháng, không có quy định kéo dài.",mn:"Câu SAI: dự bị kéo dài 24 tháng — thời kỳ dự bị cơ định 12 tháng, không gia hạn.",t:"m",q:"Khẳng định nào sau đây là sai về thời kỳ dự bị của người được kết nạp vào Đảng?",o:["Thời kỳ dự bị là 12 tháng.","Tính từ ngày chỉ bộ tổ chức lễ kết nạp.","Có thể kéo dài đến 24 tháng nếu người dự bị chưa đủ điều kiện.","Kết thúc thời kỳ dự bị, chỉ bộ xét công nhận từng người một."],c:2},{id:"vb04-26",s:"",cc:"Điều 2, khoản 4 — Điều lệ Đảng.",gt:"Nguyên văn Điều 2 khoản 4: “phục tùng kỷ luật, giữ gìn đoàn kết thống nhất trong Đảng”. Cụm cần diện ngày trước “giữ gìn đoàn kết” là “phục tùng kỷ luật”.",mn:"Trước “giữ gìn đoàn kết thống nhất trong Đảng” -. chọn “phục tùng kỷ luật”.",t:"m",q:"“Đảng viên có trách nhiệm ›, giữ gìn đoàn kết thống nhất trong Đảng; thường xuyên tự phê bình và phê bình.”",o:["nêu gương đạo đức","phục tùng kỷ luật","tham gia công tác quần chúng","tham gia công tác xây dựng Đảng"],c:1},{id:"vb04-27",s:"",cc:"Điều 3 = Điều lệ Đảng.",gt:"Đảng viên dự bị có các quyền như đảng viên chính thức, trừ quyền biểu quyết, ứng cử và bầu cử.",mn:'Đảng viên dự bị có mọi quyền, TRỪ 3 quyền: biểu quyết, ứng cử, bầu cử - nhớ "3 không”.',t:"m",q:"Khẳng định nào sau đây là đúng về đảng viên dự bị?",o:["Có đầy đủ quyền biểu quyết, ứng cử, bầu cử.","Không có quyền biểu quyết, ứng cử, bầu cử cơ quan lãnh đạo của Đảng.","Chỉ được tham dự sinh hoạt chỉ bộ khi có phép của cấp uỷ.","Chưa phải là đảng viên chính thức nên không có nghĩa vụ đóng đảng phí."],c:1},{id:"vb04-28",s:"",cc:"Điều 4, khoản 3 -— Điều lệ Đảng.",gt:"Không có hình thức kết nạp tập thể; chi bộ chỉ kết nạp từng người một.",mn:"Câu SAI: kết nạp tập thể - chỉ bộ chỉ kết nạp từng người một.",t:"m",q:"Khẳng định nào sau đây là sai về thủ tục kết nạp đảng viên?",o:["Người vào Đảng phải có đơn tự nguyện xin vào Đảng.","Phải được hai đảng viên chính thức giới thiệu.","Chi bộ xét, khi được ít nhất 2/3 số đảng viên chính thức tán thành thì đề nghị lên cấp uỷ cấp trên.","Đảng viên có thể được kết nạp tập thể nếu đủ điều kiện."],c:3},{id:"vb04-29",s:"",cc:"Điều 8, khoản 1 -— Điều lệ Đảng.",gt:"Chi bộ xem xét, đề nghị cấp có thẩm quyền xoá tên khỏi danh sách đảng viên.",mn:"Điên: xem xét, đề nghị xoá tên khỏi danh sách đảng viên — hệ quả của bộ sinh hoạ/không động phí 3 tháng.",t:"m",q:"Điền tự còn thiểu: “Đảng viên bỏ sinh hoạt chỉ bộ hoặc không đóng đảng phí 3 tháng trong năm mà không có lý do chính đáng thì chỉ bộ »",o:["Khiển trách","Đình chỉ sinh hoạt","Xem xét, đề nghị xoá tên khỏi danh sách đảng viên","Báo cáo lên Trung ương"],c:2},{id:"vb04-30",s:"",cc:"Điều 6 — Điều lệ Đảng.",gt:"Ban Chấp hành Trung ương quy định việc phát, quản lý thẻ đảng viên, hồ sơ và thủ tục chuyển sinh hoạt đảng.",mn:"Thẻ đảng viên do Ban Chấp hành Trung ương quy định - cấp Trung ương thống nhất quản lý cả nước. Chương II: NGUYÊN TẮC TỔ CHỨC VÀ CƠ CẤU TỔ CHỨC CỦA ĐẢNG",t:"m",q:"Khẳng định nào sau đây là đúng về việc phát và quản lý thẻ đảng viên?",o:["Do chi bộ nội đảng viên sinh hoạt quản lý.","Do cấp uỷ cơ sở quy định và quản lý.","Do Ban Chấp hành Trung ương quy định.","Do Ban Tổ chức Tỉnh uỷ quyết định."],c:2},{id:"vb04-31",s:"",cc:"Điều 9 - Điều lệ Đảng Cộng sản Việt Nam (Đại hội XI, 2011).",gt:"Đảng Cộng sản Việt Nam tổ chức theo nguyên tắc tập trung dân chủ, bảo đảm thống nhất ý chí và hành động.",mn:'Đảng luôn theo tập trung dân chủ (không phải "dân chủ tập trung" — nhớ tập trung dụng trước).',t:"m",q:"Đảng Cộng sản Việt Nam tổ chức theo nguyên tắc nào?",o:["Dân chủ nhân dân","Dân chủ tập trung","Tập trung dân chủ","Dân chủ toàn diện"],c:2},{id:"vb04-32",s:"",cc:"Điều 9, khoản 2 — Điều lệ Đảng.",gt:"Cơ quan lãnh đạo cao nhất của Đảng là Đại hội đại biểu toàn quốc, được tổ chức định kỳ theo Điều lệ. lưác nghiệm Điều lệ Đảng Trang là",mn:'Cao nhất toàn Đảng = Đại hội đại biểu toàn quốc. "Đại hội" là đình cao nhất.',t:"m",q:"Cơ quan lãnh đạo cao nhất của Đảng là cơ quan nào?",o:["Ban Bí thư Trung ương","Ban Chấp hành Trung ương","Đại hội đại biểu toàn quốc","Bộ Chính trị"],c:2},{id:"vb04-33",s:"",cc:"Điều 9, khoản 2 — Điều lệ Đảng.",gt:"Giữa hai kỳ Đại hội, cơ quan lãnh đạo của Đảng là Ban Chấp hành Trung ương.",mn:'Giữa hai kỳ Đại hội, lãnh đạo là Ban Chấp hành Trung ương (Đại hội "nghỉ" thì BH TỪ "gánh”).',t:"m",q:"Giữa hai kỳ Đại hội đại biểu toàn quốc, cơ quan lãnh đạo của Đảng là cơ quan nào?",o:["Ban Tổ chức Trung ương","Ban Bí thư Trung ương","Ban Chấp hành Trung ương","Bộ Chính trị"],c:2},{id:"vb04-34",s:"",cc:"Điều 9, khoản 4 = Điều lệ Đảng.",gt:"Nguyên tắc trên là nội dung cơ bản của nguyên tắc tập trung dân chủ, nhằm bảo đảm sự thống nhất trong Đảng.",mn:'"3 phục tùng” (thiểu số-cấp dưới—cá nhân) chính là nội dung tập trung dân chủ.',t:"m",q:"Nguyên tắc “thiểu số phục tùng đa số, cấp dưới phục tùng cấp trên, cá nhân phục tùng tổ chức” thể hiện nội dung nào?",o:["Kỷ luật Đảng","Nội dung nguyên tắc tập trung dân chủ","Quy định về đoàn kết nội bộ","Quy chế tổ chức Đảng"],c:1},{id:"vb04-35",s:"",cc:"Điều 9, khoản 5 — Điều lệ Đảng.",gt:"Nghị quyết chỉ có giá trị khi được hơn một nửa số thành viên trong cơ quan đó tán thành.",mn:"Nghị quyết có giá trị khi hơn 1/2 tán thành — quá bán mới xong.",t:"m",q:"Nghị quyết của cơ quan lãnh đạo của Đảng chỉ có giá trị thi hành khi có bao nhiêu số thành viên tán thành?",o:["Trên 1⁄3","Từ 1⁄2 trở lên","Hơn 1⁄2","Từ 2/3 trở lên"],c:2},{id:"vb04-36",s:"",cc:"Điều 9, khoản 5 — Điều lệ Đảng.",gt:"Đảng viên có ý kiến thuộc về thiểu số được quyền bảo lưu và báo cáo lên cấp uỷ cấp trên, song phải chấp hành nghị quyết.",mn:"Thiểu số được bảo lưu ý kiến và báo cáo lên cấp trên nhưng vẫn phải chấp hành.",t:"m",q:"Đảng viên có ý kiến thuộc về thiểu số được quyền gì?",o:["Không phát biểu trong các kỳ họp tiếp theo","Giữ ý kiến riêng nhưng không được báo cáo","Bảo lưu ý kiến và báo cáo lên cấp uỷ cấp trên","Không được tham gia biểu quyết"],c:2},{id:"vb04-37",s:"",cc:"Điều 10, khoản Ì - Điều lệ Đồng.",gt:"Hệ thống tổ chức của Đảng được lập tương ứng với hệ thống tổ chức hành chính của Nhà nước.",mn:'Tổ chức Đảng lập tương ứng hệ thống hành chính Nhà nước (Đảng "soi" theo hành chính).',t:"m",q:"Hệ thống tổ chức của Đảng được lập tương ứng với hệ thống nào sau đây?",o:["Hệ thống chính trị","Hệ thống hành chính của Nhà nước","Hệ thống Mặt trận Tổ quốc","Hệ thống dân cử"],c:1},{id:"vb04-38",s:"",cc:"Điều I0, khoản 3 — Điều lệ Đảng. lưác nghiện Điều lệ Đảng Trang lỗ",gt:"Cấp uỷ cấp trên trực tiếp có quyền quyết định lập hoặc giải thể đảng bộ, chi bộ trực thuộc.",mn:"Cấp uỷ trên trực tiếp có quyền lập hoặc giải thể đảng bộ, chỉ bộ dưới.",t:"m",q:"Cấp uỷ cấp trên trực tiếp có quyền gì đối với tổ chức đảng trực thuộc?",o:["Bổ nhiệm đảng viên chính thức","Giải thể hoặc thành lập đảng bộ, chỉ bộ trực thuộc","Quy định nhân sự cấp uỷ","Chỉ định Ban Tổ chức cơ sở"],c:1},{id:"vb04-39",s:"",cc:"Điều I1, khoản 6 = Điều lệ Đảng.",gt:"Đại hội hợp lệ khi có ít nhất hai phần ba số đại biểu hoặc đảng viên được triệu tập tham dự.",mn:"Đại hội hợp lệ khi có ít nhất 2/3 đại biểu dự (hai phần ba).",t:"m",q:"Đại hội của Đảng chỉ được coi là hợp lệ khi có ít nhất bao nhiêu phần trăm đại biểu hoặc đảng viên được triệu tập tham dự?",o:["Một nửa","Hơn một nửa","Hai phần ba","Ba phần tư"],c:2},{id:"vb04-40",s:"",cc:"Điều 12, khoản 3 ~ Điều lệ Đảng.",gt:"Người trúng cử phải được số phiếu bầu quá một nửa so với tổng số đại biểu được triệu tập.",mn:"Trúng cử cấp uỷ = quá 1⁄2 số phiếu so với tổng đại biểu triệu tập.",t:"m",q:"Người trúng cử vào cấp uỷ phải đạt số phiếu bầu như thế nào mới hợp lệ?",o:["Đạt đúng 50% tổng số phiếu","Đạt quá một nửa số phiếu so với tổng số đại biểu được triệu tập","Đạt từ hai phần ba số phiếu trở lên","Đạt số phiếu cao nhất trong danh sách bầu"],c:1},{id:"vb04-41",s:"",cc:"Điều 12, khoản 2 — Điều lệ Đảng Cộng sản Việt Nam (Đại hội XI, 2011). ¬",gt:"Số lượng Uỷ viên Ban Chấp hành Trung ương do Đại hội đại biểu toàn quốc quyết định.",mn:"Số lượng Uỷ viên BCH TỰ do Đại hội đại biểu toàn quốc quyết định.",t:"m",q:"Ai quyết định số lượng Uỷ viên Ban Chấp hành Trung ương Đảng?",o:["Bộ Chính trị","Ban Tổ chức Trung ương","Đại hội đại biểu toàn quốc","Ban Chấp hành Trung ương khóa trước"],c:2},{id:"vb04-42",s:"",cc:"Điều 13, khoản 1 ¬ Điều lệ Đảng.",gt:"Cấp uỷ khóa mới được công nhận chính thức khi có quyết định chuẩn y của cấp uỷ cấp trên trực tiếp.",mn:"Cấp uỷ mới chính thức khi có chuẩn y của cấp uỷ trên trực tiếp (bầu xong chưa đủ).",t:"m",q:"Cấp uỷ khóa mới được công nhận chính thức khi nào?",o:["Ngay sau khi bầu","Khi có quyết định chuẩn y của cấp uỷ cấp trên trực tiếp","Sau khi tổ chức họp đầu tiên","Khi có nghị quyết thông qua nhiệm kỳ mỗi"],c:1},{id:"vb04-43",s:"",cc:"Điều 13, khoản 3 - Điều lệ Động.",gt:"Cấp uỷ cấp trên có thể điều động một số cấp uỷ viên cấp dưới, nhưng không quá 1/3 tổng số cấp uỷ viên do đại hội đã bầu.",mn:"Điều động cấp uỷ viên dưới: không quá 1⁄3 tổng số.",t:"m",q:"Khi thật cần thiết, cấp uỷ cấp trên có thể điều động bao nhiêu cấp uỷ viên cấp dưới?",o:["Không quá 1/5 tổng số cấp uỷ viên","Không quá 1⁄3 tổng số cấp uỷ viên","Không quá 1⁄2 tổng số cấp uỷ viên","Không giới hạn số lượng"],c:1},{id:"vb04-44",s:"",cc:"Điều 13, khoản 2 ~ Điều lệ Đảng. g",gt:"Việc bổ sung cấp uỷ viên do cấp uỷ đề nghị, cấp uỷ cấp trên trực tiếp quyết định.",mn:"Bổ sung cấp uỷ viên thiểu: cấp uỷ trên trực tiếp quyết định.",t:"m",q:"Ai có thẩm quyền quyết định việc bổ sung cấp uỷ viên khi bị thiếu?",o:["Đại hội đảng viên","Cấp uỷ cấp trên trực tiếp","Cấp uỷ cơ sở","Bộ Chính trị"],c:1},{id:"vb04-45",s:"",cc:"Điều 13, khoản 5 = Điều lệ Đảng.",gt:"Cấp uỷ cấp trên trực tiếp chỉ định cấp uỷ chính thức đối với tổ chức đảng được thành lập, chia tách, hợp nhất, sáp nhập trong nhiệm kỳ.",mn:"Lập/chia/hợp/sáp nhập trong nhiệm kỳ: cấp uỷ trên trực tiếp chỉ định cấp uỷ chính thức.",t:"m",q:"Khi tổ chức đảng mới được thành lập, chia tách, hợp nhất hoặc sáp nhập trong nhiệm kỳ, cấp uỷ nào có quyền chỉ định cấp uỷ chính thức?",o:["Cấp uỷ cấp trên trực tiếp","Ban Chấp hành Trung ương","Đại hội cấp mới","Ban Thường vụ tỉnh uỷ"],c:0},{id:"vb04-46",s:"",cc:"Điều 13, khoản 4 - Điều lộ Đảng.",gt:"Cấp uỷ viên xin rút khỏi cấp uỷ do cấp uỷ xem xét và đề nghị lên cấp uỷ cấp trên trực tiếp quyết định.",mn:"Xin rút khỏi cấp uỷ: cấp uỷ trên trực tiếp quyết định (nhớ: mọi việc nhân sự do trên trực tiếp chốt).",t:"m",q:"Cấp uỷ viên muốn xin rút khỏi cấp uỷ phải do ai quyết định?",o:["Chỉ bộ nơi công tác","Đại hội cấp đó","Cấp uỷ cấp trên trực tiếp","Ban Bí thư Trung ương"],c:2},{id:"vb04-47",s:"",cc:"Điều 12, khoản 3 — Điều lệ Đảng. ¬",gt:"Bầu cử trong Đảng được tiến hành bằng phiếu kín, bảo đảm dân chủ và khách quan.",mn:"Bầu cử trong Đảng luôn bằng phiếu kín.",t:"m",q:"Việc bầu cử trong Đảng được tiến hành theo hình thức nào?",o:["Bỏ phiếu công khai","Bỏ phiếu kín","Giơ tay biểu quyết","Đại biểu biểu quyết bằng thẻ Đảng"],c:1},{id:"vb04-48",s:"",cc:"Điều 14, khoản 1 - Điều lệ Dụng.",gt:"Cấp uỷ mỗi cấp lập các cơ quan tham mưu, giúp việc theo hướng dẫn của Ban Chấp hành Trung ương.",mn:"Lập cơ quan tham mưu, giúp việc theo hướng dẫn của Ban Chấp hành Trung ương.",t:"m",q:"Cấp uỷ mỗi cấp lập các cơ quan tham mưu, giúp việc theo hướng dẫn của ai?",o:["Bộ Chính trị","Ban Bí thư","Ban Chấp hành Trung ương","Cấp uỷ cấp trên trực tiếp"],c:2},{id:"vb04-49",s:"",cc:"Điều 9 - Điều lộ Đảng Cộng sản Việt Nam (Đại hội XI, 2011).",gt:"Đảng Cộng sản Việt Nam tổ chức theo nguyên tắc tập trung dân chủ, bảo đảm sự thống nhất ý chí, hành động và ký luật trong toàn Đảng.",mn:"Nguyên tắc đúng: tập trung dân chủ (tập trung trước, dân chủ sau).",t:"m",q:"Khẳng định nào sau đây là đúng về nguyên tắc tổ chức của Đảng Cộng sản Việt Nam?",o:["Tổ chức theo nguyên tắc dân chủ tập trung.","Tổ chức theo nguyên tắc tập trung dân chủ.","Tổ chức theo nguyên tắc tập thể lãnh đạo, cá nhân phụ trách.","Tổ chức theo nguyên tắc đa số quyết định thiểu số."],c:1},{id:"vb04-50",s:"",cc:"Điều 9, khoản 4 — Điều lệ Đảng.",gt:"Các tổ chức trong toàn Đảng phục tùng Đại hội đại biểu toàn quốc và Ban Chấp hành Trung ương.",mn:"Toàn Đảng phục tùng Đại hội đại biểu toàn quốc và Ban Chấp hành Trung ương - hai đầu tàu cao nhất.",t:"m",q:"Điền cụm từ con thiểu: “Thiểu số phục tùng đa số, cấp dưới phục tùng cấp trên, cá nhân phục tùng tổ chức, các tổ chức trong toàn Đảng phục tùng ”.",o:["Bộ Chính trị","Ban Bí thư","Đại hội đại biểu toàn quốc và Ban Chấp hành Trung ương","Cấp uỷ cấp trên trực tiếp"],c:2},{id:"vb04-51",s:"",cc:"Điều 9, khoản 1 và 3 = Điều lệ Đảng.",gt:"Cấp uỷ các cấp không tự quyết định nhiệm kỳ của mình mà phải tuân theo quy định chung và điều lệ của Đảng.",mn:"Câu SAI: cấp ủy KHÔNG tự quyết định nhiệm kỳ - phải theo Điều lệ.",t:"m",q:"Khẳng định nào sau đây là sai theo quy định của Điều lệ Đảng?",o:["Cơ quan lãnh đạo các cấp của Đảng do bầu cử lập ra.","Đại hội đại biểu toàn quốc là cơ quan lãnh đạo cao nhất của Đảng.","Các cấp uỷ tự quyết định nhiệm kỳ hoạt động của mình.","Cấp uỷ báo cáo và chịu trách nhiệm trước đại hội cùng cấp và cấp trên."],c:2},{id:"vb04-52",s:"",cc:"Điều 11, khoản 6 - Điều lệ Đảng.",gt:"Đại hội hợp lệ khi có ít nhất hai phần ba số đại biểu được triệu tập và hai phần ba số tổ chức đảng trực thuộc có đại biểu tham dự.",mn:"Đại hội hợp lệ cần 2/3 tổ chức đảng trực thuộc có đại biểu dự (cùng còn số 2/3).",t:"m",q:"Đại hội Đảng chỉ hợp lệ khi có ít nhất bao nhiêu phần trăm tổ chức đảng trực thuộc có đại biểu tham dự?",o:["Một nửa","Hơn một nửa","Hai phần ba","Từ ba phần tư trở lên"],c:2},{id:"vb04-53",s:"",cc:"Điều 9, khoản 5 — Điều lệ Đảng.",gt:"Đảng viên có ý kiến thuộc thiểu số được quyền bảo lưu và báo cáo lên cấp uỷ cấp trên, nhưng vẫn phải chấp hành nghị quyết của Đảng.",mn:"Thiểu số: bảo lưu và báo cáo lên cấp trên, vẫn chấp hành nghị quyết.",t:"m",q:"Khẳng định nào sau đây là đúng về quyền của đảng viên có ý kiến thuộc thiểu số?",o:["Không được phát biểu thêm tại các kỳ họp sau.","Chỉ được báo cáo trong phạm vi chỉ bộ.","Được quyền bảo lưu ý kiến và báo cáo lên cấp uỷ cấp trên.","Không được nêu ý kiến khi đã có nghị quyết. ¬"],c:2},{id:"vb04-54",s:"",cc:"Điều 9, khoản 5 - Điều lệ Đảng.",gt:"Nghị quyết chỉ có giá trị khi có hơn một nửa số thành viên trong cơ quan đó tán thành, không phải 1⁄3.",mn:"SA] - phải hơn 1/2 tán thành chứ không phải 1⁄3.",t:"m",q:"Nhận định sau đây đúng hay sai? “Nghị quyết của cơ quan lãnh đạo các cấp của Đảng chỉ có giá trị thi hành khi có ít nhất 1/3 số thành viên tán thành.”",o:["Đúng","Sai"],c:1},{id:"vb04-55",s:"",cc:"Điều 11, khoản 5 - Điều lệ Dụng.",gt:"Đại biểu đang bị đình chỉ sinh hoạt hoặc tạm giam không được công nhận tư cách đại biểu dự đại hội.",mn:"Đang bị tạm giam/đình chỉ sinh hoạt thì KHÔNG công nhận tư cách đại biểu.",t:"m",q:"Tình huống: Một đại biểu được đại hội cấp dưới bầu hợp lệ, nhưng đang bị tạm giam theo quyết định của cơ quan điều tra. Đại hội cấp trên cú quyền công nhận tư cách đại biểu này không?",o:["Có, nếu chưa có bản án kết tội.","Không, vị thuộc trường hợp bị đình chỉ sinh hoạt.","Có, nếu được Ban Tổ chức Trung ương cho phép.","Có thể xem xét theo từng trường hợp."],c:1},{id:"vb04-56",s:"",cc:"Điều 12, khoản 3 = Điều lệ Đảng.",gt:"Người trúng cử phải được số phiếu bầu quá một nửa so với tổng số đại biểu được triệu tập.",mn:"Trúng cử = quá một nửa phiếu (không phải cao nhất, không phải 273).",t:"m",q:"Khẳng định nào sau đây là đúng về người trúng cử trọng bầu cử cấp uỷ?",o:["Người trúng cử phải có số phiếu cao nhất trong danh sách.","Người trúng cử phải được số phiếu quá một nửa so với tổng số đại biểu được triệu tập.","Người trúng cử phải đạt ít nhất 2/3 tổng số phiếu.","Người trúng cử phải đạt đúng 50% tổng số phiếu."],c:1},{id:"vb04-57",s:"",cc:"Điều 12, khoản 1 -— Điều lệ Đảng.",gt:"Cấp uỷ viên phải chấp hành nghiêm nguyên tắc tổ chức và sinh hoạt Đảng, kỷ luật của Đảng và pháp luật của Nhà nước.",mn:"Cấp uỷ viên phải chấp hành nghiêm nguyên tắc tổ chức và ký luật của Đảng.",t:"m",q:"Điền cụm từ con thiểu: “Cấp uỷ viên phải có đủ tiêu chuẩn về phẩm chất chính trị, đạo đức cách mạng, lối sống lành mạnh;; có kiến thức và năng lực lãnh đạo tập thể.”",o:["tuân thủ quy định công tác cán bộ","chấp hành nghiêm nguyên tắc tổ chức và kỷ luật của Đảng","hoàn thành xuất sắc nhiệm vụ chuyên môn","gắn bó mật thiết với nhân dân"],c:1},{id:"vb04-58",s:"",cc:"Điều 14 — Điều lệ Đảng.",gt:"Việc lập cơ quan tham mưu, giúp việc không cần Ban Bí thư phê duyệt trực tiếp mà thực hiện theo hướng dẫn của Ban Chấp hành Trung ương.",mn:"Câu SAI: KHÔNG cần Ban Bí thư phê duyệt trực tiếp - theo hướng dẫn của BCH Trung ương.)) Chương I1: CƠ QUAN LÃNH ĐẠO CỦA ĐẢNG Ở CẤP TRUNG ƯƠNG",t:"m",q:"Khẳng định nào sau đây là sai về việc lập các cơ quan tham mưu, giúp việc của cấp uỷ?",o:["Cấp uỷ lập cơ quan tham mưu, giúp việc theo hướng dẫn của Ban Chấp hành Trung ương.","Khi cần, cấp uỷ có thể lập tiểu ban, hội đồng, tổ công tác.","Việc lập cơ quan tham mưu, giúp việc phải được Ban Bí thư phê duyệt trực tiếp.","Cấp uỷ được giải thể các tổ chức giúp việc khi hoàn thành nhiệm vụ."],c:2},{id:"vb04-59",s:"",cc:"Diều I5, khoản 1 — Điều lộ Đảng Cộng sản Việt Nam (Đại hội XI, 2011).",gt:"Đại hội đại biểu toàn quốc được triệu tập thường lệ 5 năm một lần, có thể sớm hoặc muộn hơn nhưng không quá 1 năm.",mn:"Đại hội toàn quốc: 5 năm/lần, xê dịch không quá 1 năm. Nhớ 'năm năm:",t:"m",q:"Đại hội đại biểu toàn quốc do Ban Chấp hành Trung ương triệu tập thường lệ một lần.",o:["bốn năm","năm năm","sáu năm","ba năm"],c:1},{id:"vb04-60",s:"",cc:"Điều l5, khoản 3 - Điều lệ Dụng.",gt:"Ban Chấp hành Trung ương có quyền triệu tập Đại hội đại biểu toàn quốc bất thường khi xét thấy cần hoặc có hơn một nửa số cấp uỷ trực thuộc yêu cầu.",mn:"Bất thường ai triệu tập? Ban Chấp hành Trung ương - cơ quan bầu ra thì có quyền gọi họp lại.",t:"m",q:"Cơ quan có thẩm quyền triệu tập Đại hội đại biểu toàn quốc bất thường khi thấy cần thiết là cơ quan nào?",o:["Bộ Chính trị","Ban Bí thư","Ban Chấp hành Trung ương","Ban Tổ chức Trung ương"],c:2},{id:"vb04-61",s:"",cc:"Điều 15, khoản 2 — Điều lệ Đảng. lưác nghiện) Điều lệ Đảng",gt:"Đại hội có quyền bổ sung, sửa đổi Cương lĩnh chính trị và Điều lệ Đảng khi cần thiết.",mn:"Đại hội sửa được 2 văn kiện gốc: Cương lĩnh chính trị và Điều lệ Đảng ~ hai thứ nền tảng nhất.",t:"m",q:"Đại hội đại biểu toàn quốc có quyền bổ sung, sửa đổi văn kiện nào của Đảng khi cần thiết?",o:["Cương lĩnh chính trị và Điều lệ Đảng","Nghị quyết Trung ương và các chỉ thị","Quy chế làm việc và quy định về đảng viên","Chiến lược phát triển kinh tế — xã hội"],c:0},{id:"vb04-62",s:"",cc:"Điều 16, khoản 3 — Điều lệ Đảng.",gt:"Ban Chấp hành Trung ương họp thường lệ 6 tháng một lần, có thể họp bất thường khi cần.",mn:"Trung ương họp thường lệ 6 tháng/lần - nửa năm một kỳ.",t:"m",q:"Ban Chấp hành Trung ương họp thường lệ bao lâu một lần?",o:["Ba tháng","Sáu tháng","Một năm","Hai năm"],c:1},{id:"vb04-63",s:"",cc:"Điều 17, khoản 1 - Điều lệ Đảng.",gt:"Ban Bí thư là cơ quan lãnh đạo công việc hằng ngày của Đảng (do Ban (hấp hành Trung ương lập ra, gồm Tổng Bí thư và một số Uỷ viên Ban Bí thư). Bộ Chính trị lãnh đạo, kiểm tra việc thực hiện nghị quyết và quyết định chủ trương, chính sách, tổ chức, cán bộ — không phải công việc hằng ngày.",mn:"“Hằng ngày” ¬„ Ban Bí thư. Bộ Chính trị lo chủ trương, chính sách, cán bộ.",t:"m",q:"Ban Chấp hành Trung ương bầu cơ quan nào để lãnh đạo công tác hằng ngày của Đảng?",o:["Ban Bí thư","Bộ Chính trị","Văn phòng Trung ương Đảng","Ban Tổ chức Trung ương"],c:0},{id:"vb04-64",s:"",cc:"Điều 17, khoản 1 — Điều lệ Đảng.",gt:"Ban Chấp hành Trung ương bầu Tổng Bí thư trong số Uỷ viên Bộ Chính trị.",mn:"Ai bầu Tổng Bí thư? Ban Chấp hành Trung ương bầu, chọn từ trong Uỷ viên Bộ Chính trị.",t:"m",q:"Tổng Bí thư do cơ quan nào bầu trong số Uỷ viên Bộ Chính trị?",o:["Ban Bí thư","Đại hội đại biểu toàn quốc","Ban Chấp hành Trung ương","Bộ Chính trị"],c:2},{id:"vb04-65",s:"",cc:"Điều I7, khoản Ì - Điều lệ Dụng.",gt:"Tổng Bí thư giữ chức vụ không quá hai nhiệm kỳ liên tiếp, bảo đảm tính kế thừa và đổi mới trong lãnh đạo.",mn:"Tổng Bí thư không quá 2 nhiệm kỳ liên tiếp - nhớ số '2'.",t:"m",q:"Đồng chí Tổng Bí thư giữ chức vụ không quá nhiệm kỳ liên tiếp.",o:["một","hai","ba","bốn"],c:1},{id:"vb04-66",s:"",cc:"Điều 17, khoản 2 - Điều lệ Động.",gt:"Bộ Chính trị lãnh đạo và kiểm tra, giám sát việc thực hiện nghị quyết của Đại hội và Ban Chấp hành Trung ương.",mn:"Lãnh đạo, kiểm tra thực hiện nghị quyết Đại hội là Bộ Chính trị.",t:"m",q:"Cơ quan nào có nhiệm vụ lãnh đạo và kiểm tra việc thực hiện nghị quyết của Đại hội đại biểu toàn quốc?",o:["Ban Bí thư","Ban Chấp hành Trung ương","Bộ Chính trị","Ban Tổ chức Trung ương"],c:2},{id:"vb04-67",s:"",cc:"Điều 17, khoản 3 — Điều lệ Đảng.",gt:"Ban Bí thư lãnh đạo công việc hằng ngày của Đảng, chỉ đạo công tác xây dựng Đảng và công tác quần chúng.",mn:'Ban Bí thư chỉ đạo xây dựng Đảng và công tác quần chúng - nhớ "Đảng - dân.',t:"m",q:"Ban Bí thư lãnh đạo công việc hằng ngày của Đảng và chỉ đạo công tác nào dưới đây?",o:["Xây dựng Đảng và công tác quần chúng","Quan hệ quốc tế và đối ngoại","Xây dựng pháp luật và chính sách xã hội","Cải cách hành chính và tài chính Đảng"],c:0},{id:"vb04-68",s:"",cc:"Điều 17, khoản 3 ~— Điều lệ Đảng.",gt:"Ban Bí thư kiểm tra, giám sát việc thực hiện các nghị quyết, chỉ thị của Đảng về kinh tế, xã hội, quốc phòng, an ninh và đối ngoại.",mn:"Dan Bí thư giám sát 5 lĩnh vực: Kinh tế, xã hội, quốc phòng, an ninh, đối ngoại (K-X-()-A-Ð).",t:"m",q:"Ban Bí thư có trách nhiệm kiểm tra, giám sát việc thực hiện các nghị quyết, chỉ thị của Đảng về những lĩnh vực nào sau đây?",o:["Kinh tế, xã hội, quốc phòng, an ninh, đối ngoại","Chính trị, pháp luật, tôn giáo, văn hoá","Khoa học, công nghệ, tài nguyên, môi trường","Đào tạo, giáo dục, y tế, dân số"],c:0},{id:"vb04-69",s:"",cc:"Điều 15, khoản 1 — Điều lệ lang Cộng sản Việt Nam (Đại hội X1, 2011).",gt:"Đại hội đại biểu toàn quốc do Ban Chấp hành Trung ương triệu tập thường lệ 5 năm một lần, có thể sớm hoặc muộn hơn nhưng không quá 1 năm.",mn:"Đúng là 5 năm/lần, sớm hoặc muộn không quá 1 năm - loại ngày 4 năm, 6 năm.",t:"m",q:"Khẳng định nào sau đây là đúng về nhiệm kỳ tổ chức Đại hội đại biểu toàn quốc?",o:["Đại hội tổ chức 4 năm một lần.","Đại hội tổ chức 5 năm một lần, có thể sớm hoặc muộn hơn không quá 1 năm.","Đại hội tổ chức 6 năm một lần.","Đại hội chỉ họp khi Ban Chấp hành Trung ương yêu cầu."],c:1},{id:"vb04-70",s:"",cc:"Điều 15, khoản 3 — Điều lệ Dụng.",gt:"Ban Chấp hành Trung ương có quyền triệu tập Đại hội đại biểu toàn quốc bất thường khi có trên một nửa số cấp uỷ trực thuộc yêu cầu.",mn:"Trên một nửa cấp uỷ yêu cầu.„ Ban Chấp hành Trung ương triệu tập bất thường.",t:"m",q:"Khi có hơn một nửa số cấp uỷ trực thuộc yêu cầu, cơ quan nào có trách nhiệm triệu tập Đại hội đại biểu toàn quốc bất thường?",o:["Bộ Chính trị","Ban Chấp hành Trung ương","Ban Bí thư","Ban Tổ chức Trung ương"],c:1},{id:"vb04-71",s:"",cc:"Điều 15, khoản 2 - Điều lệ Đảng.",gt:"Đại hội đại biểu toàn quốc có nhiệm vụ bầu Ban Chấp hành Trung ương, là cơ quan lãnh đạo giữa hai kỳ đại hội.",mn:"Thẩm quyền Đại hội: bầu Ban Chấp hành Trung ương - cơ quan lãnh đạo giữa hai kỳ đại hội.",t:"m",q:"Nhiệm vụ nào sau đây thuộc thẩm quyền của Đại hội đại biểu toàn quốc?",o:["Chỉ đạo công tác hằng ngày của Đảng","Bầu Ban Chấp hành Trung ương","Giải quyết khiếu nại đảng viên","Phê chuẩn kết quả bầu Ban Bí thư"],c:1},{id:"vb04-72",s:"",cc:"Điều!6, khoản 2 ~ Điều lệ Đảng.",gt:"Ban Chấp hành Trung ương căn cứ tình hình thực tế để chỉ đạo thí điểm một số chủ trương mới.",mn:"Trung ương được chỉ đạo thí điểm chủ trương mới — căn cứ tình hình thực tế.",t:"m",q:"Ban Chấp hành Trung ương căn cứ tình hình thực tế có thể quyết định chỉ đạo việc gì?",o:["Thí điểm một số chủ trương mới","Sửa đổi Điều lệ Đảng","Giải tán cấp uỷ địa phương","Quy định số lượng đảng viên tối đa của chi bộ"],c:0},{id:"vb04-73",s:"",cc:"Điều 16, khoản 1 — Điều lệ Đảng.",gt:"Ban Chấp hành Trung ương tổ chức chỉ đạo thực hiện Cương lĩnh, Điều lệ, nghị quyết của Đại hội và quyết định những chủ trương, chính sách lớn của Đảng.",mn:"Quyết chủ trương đối nội, đối ngoại, quần chúng, xây dựng Đảng ¬› Ban Chấp hành Trung ương.",t:"m",q:"Cơ quan nào có nhiệm vụ quyết định những chủ trương, chính sách về đối nội, đối ngoại, công tác quần chúng và xây dựng Đảng?",o:["Bộ Chính trị","Ban Chấp hành Trung ương","Ban Bí thư","Đại hội đại biểu toàn quốc"],c:1},{id:"vb04-74",s:"",cc:"Điều 17, khoản 1 - Điều lệ Đảng.",gt:"Ban Chấp hành Trung ương chứ không phải Bộ Chính trị có quyền bầu Tổng Bí thư trong số Uỷ viên Bộ Chính trị.",mn:"Câu SAI là Bộ Chính trị bầu Tổng Bí thư - thực ra Trung ương mới bầu.",t:"m",q:"Khẳng định nào sau đây là sai về quyền hạn của Bộ Chính trị?",o:["Lãnh đạo và kiểm tra việc thực hiện nghị quyết Đại hội","Quyết định những vấn đề về chủ trương, tổ chức, cán bộ","Báo cáo công việc trước Ban Chấp hành Trung ương","Quyền bầu Tổng Bí thư trong số Uỷ viên Trung ương"],c:3},{id:"vb04-75",s:"",cc:"Điều 17, khoản 3 — Điều lệ Đảng.",gt:"Ban Bí thư chỉ đạo sự phối hợp hoạt động giữa các tổ chức trong hệ thống chính trị. ¬",mn:"Ban Bí thư điều phối phối hợp giữa các tổ chức trong hệ thống chính trị.",t:"m",q:"Ban Bí thư có trách nhiệm lãnh đạo công việc hằng ngày của Đảng, chỉ đạo sự phối hợp giữa các tổ chức nào?",o:["Giữa các bộ, ngành của Nhà nước","Giữa các tổ chức trong hệ thống chính trị","Giữa các tổ chức đoàn thể xã hội","Giữa các cơ quan thuộc Chính phủ"],c:1},{id:"vb04-76",s:"",cc:"Điều 17, khoản 2 ~ Điều lệ Đảng.",gt:"Bộ Chính trị có nhiệm vụ quyết định triệu tập và chuẩn bị nội dung các kỳ họp của Ban Chấp hành Trung ương.",mn:"Nhiệm vụ Bộ Chính trị: chuẩn bị nội dung, triệu tập các kỳ họp Trung ương.",t:"m",q:"Trường hợp nào sau đây phản ánh đúng nhiệm vụ của Bộ Chính trị theo Điều lệ Đảng?",o:["Ban hành các nghị quyết thay thế nghị quyết Đại hội","Chuẩn bị nội dung, triệu tập các kỳ họp Ban Chấp hành Trung ương","Quyết định kết nạp đảng viên mọi","Lãnh đạo công tác hằng ngày của Đảng"],c:1},{id:"vb04-77",s:"",cc:"Điều 17, khoản 1 - Điều lệ Đảng.",gt:"Ban Chấp hành Trung ương bầu Bộ Chính trị, Ban Bí thư và Ủy ban Kiểm tra Trung ương. __] Cập nhật 2025: cơ quan tham mưu, giúp việc của Trung ương gồm Ban Tổ chức, Ban Tuyên giao và Dân vấn, Ban Nội chính, Bản Chính sách — Chiến lược, Văn phòng Trung ương (không do Ban Chấp hành Trung ương bầu); Ban Tuyên giao và Ban Dân vận đã hợp nhất, Bản Đối ngoại và Ban Kinh tố Trung ương đã kết thúc hoạt động.",mn:"Trung ương bầu bộ ba: Bộ Chính trị - Ban Bí thư - Uỷ ban Kiểm tra Trung ương. | Nhớ: chỉ 3 cơ quan do BCH TW bầu = Bộ Chính trị - Ban Bí thư — UBKT TW.",t:"m",q:"Khẳng định nào sau đây là đúng về cơ quan do Ban Chấp hành Trung ương bầu ra?",o:["Bộ Chính trị, Ban Bí thư, Ủy ban Kiểm tra Trung ương","Ban Tổ chức Trung ương, Ban Tuyên giao và Dân vận Trung ương","Ban Nội chính Trung ương và Văn phòng Trung ương","Bản Chính sách, Chiến lược Trung ương và Ban Nội chính Trung ương"],c:0},{id:"vb04-78",s:"",cc:"Điều 15, khoản 2 = Điều lệ Đảng.",gt:"Ban Chấp hành Trung ương xem xét việc chuyển Uỷ viên dự khuyết đủ điều kiện thay thế Uỷ viên chính thức khi khuyết.",mn:"Khuyết Uỷ viên chính thức -. Ban Chấp hành Trung ương xét chuyển Uỷ viên dự khuyết lên thay. Chương IV: CƠ QUAN LÃNH ĐẠO CỦA ĐẢÁNG Ở CÁC CẤP ĐỊA PHƯƠNG",t:"m",q:"Nếu Ban Chấp hành Trung ương khuyết Uỷ viên chính thức, cơ quan nào xem xét việc chuyển Uỷ viên dự khuyết đủ điều kiện thay thế?",o:["Bộ Chính trị","Ban Chấp hành Trung ương","Đại hội đại biểu toàn quốc","Ban Tổ chức Trung ương"],c:1},{id:"vb04-79",s:"",cc:"Diều!8, khoản 1 - Điều lệ Đảng Cộng sản Việt Nam (Đại hội XI, 2011).",gt:"Đại hội đại biểu đảng bộ cấp tỉnh, thành phố trực thuộc Trung ương được triệu tập thường lệ 5 năm một lần, có thể sớm hoặc muộn hơn nhưng không quá l năm.",mn:"Đại hội đảng bộ tỉnh, thành phố: 5 năm/lần - nhớ nhiệm kỳ chuẩn của Đảng.",t:"m",q:"Đại hội đại biểu đảng bộ tỉnh, thành phố trực thuộc Trung ương do cấp uỷ cùng cấp triệu tập thường lệ một lần.",o:["ba năm","bốn năm","năm năm","sáu năm"],c:2},{id:"vb04-80",s:"",cc:"Điều 18, khoản 1 — Điều lệ Đảng.",gt:"Thời gian triệu tập đại hội cấp địa phương có thể sớm hoặc muộn hơn, nhưng không quá 1 năm. | Cập nhật: theo mô hình tổ chức đảng 2 cấp (QĐÐ 20-()Ð/TW năm 2026), cấp địa phương gồm cấp tỉnh và cấp xã (xã, phường, đặc khu), không còn cấp huyện.",mn:"Sớm hay muộn cũng không quá 1 năm - lệch tối đa dụng một năm.",t:"m",q:"Đại hội đại biểu đảng bộ địa phương (cấp tỉnh, cấp xã) có thể triệu tập sớm hoặc muộn hơn thời hạn quy định nhưng không quá",o:["sáu tháng","một năm","hai năm","chín tháng"],c:1},{id:"vb04-81",s:"",cc:"Điều 18, khoản 2 = Điều lệ Đảng.",gt:"Đại hội đảng bộ các cấp có nhiệm vụ bầu cấp uỷ và bầu đại biểu dự đại hội cấp trên.",mn:'Nhiệm vụ cốt lõi: bầu cấp uỷ + bầu đại biểu dự đại hội cấp trên ~- chi "bầu”, không khen thưởng hay bổ nhiệm.',t:"m",q:"Một trong các nhiệm vụ của đại hội đại biểu đảng bộ các cấp là",o:["Xét duyệt khen thưởng đảng viên","Bầu cấp uỷ và đại biểu dự đại hội cấp trên","Bổ nhiệm cán bộ chủ chốt địa phương","Báo cáo công tác kiểm tra Đảng toàn khóa"],c:1},{id:"vb04-82",s:"",cc:"Điều 18, khoản 3 — Điều lệ Đảng.",gt:"Đại hội bất thường được triệu tập khi có trên một nửa số cấp uỷ trực thuộc yêu cầu và được cấp uỷ cấp trên trực tiếp đồng ý.",mn:'Đại hội bất thường: trên một nửa cấp uỷ yêu cầu và cấp uỷ cấp trên %! trực tiếp đồng ý -— nhớ "cấp trên trực tiếp".',t:"m",q:"Đại hội đại biểu đảng bộ bất thường được triệu tập khi có trên một nửa số cấp uỷ trực thuộc yêu cầu và được đồng ý.",o:["cấp uỷ cấp trên trực tiếp","Bộ Chính trị","Ban Bí thư","Ban Tổ chức Trung ương"],c:0},{id:"vb04-83",s:"",cc:"Điều 19, khoản 1 — Điều lệ Đảng.",gt:"Cấp uỷ địa phương lãnh đạo thực hiện nghị quyết đại hội đại biểu và nghị quyết, chỉ thị của cấp trên. _- | Cập nhật: theo mô hình tổ chức đảng 2 cấp (QĐÐ 20-Q)Ð/TW năm 2026), cấp địa phương gồm cấp tỉnh và cấp xã (xã, phường, đặc khu), không còn cấp huyện.",mn:"Cấp uỷ thực hiện nghị quyết đại hội và nghị quyết, chỉ thị của cấp trên - trong Đảng theo cấp trên, không theo pháp luật Nhà nước.",t:"m",q:"Cấp uỷ địa phương (cấp tỉnh, cấp xã) lãnh đạo thực hiện nghị quyết của đại hội đại biểu và.",o:["nghị quyết, chỉ thị của cấp trên","quy định pháp luật của Nhà nước","hướng dẫn của các tổ chức đoàn thể","kế hoạch của chính quyền địa phương"],c:0},{id:"vb04-84",s:"",cc:"liệu 19, khoản 2 ~ Điều lệ Đảng.",gt:"Hội nghị cấp uỷ địa phương do ban thường vụ triệu tập thường lệ 3 tháng một lần. _- ] Cập nhật: theo mô hình tổ chức đảng 2 cấp (QĐ 20-QĐ/TW năm 2026), cấp địa phương gồm cấp tỉnh và cấp xã (xã, phường, đặc khu), không còn cấp huyện.",mn:"Hội nghị tỉnh/huyện uỷ họp 3 tháng/lần - nhớ môi quý một lần.",t:"m",q:"Hội nghị cấp uỷ địa phương (tỉnh uỷ, đảng uỷ xã, phường) do ban thường vụ triệu tập thường lệ một lần.",o:["mỗi tháng","hai tháng","ba tháng","sáu tháng"],c:2},{id:"vb04-85",s:"",cc:"Điều 20, khoản 1 — Điều lệ Đảng.",gt:"Hội nghị cấp uỷ bầu ban thường vụ trong số các uỷ viên cấp uỷ; con bí thư và phó bí thư thì bầu trong số uỷ viên thường vụ (Điều 20, khoản 1). -j Cập nhật: theo mô hình tổ chức đảng 2 cấp (QĐ 20-QĐ/TW năm 2026), cấp địa phương gồm cấp tỉnh và cấp xã (xã, phường, đặc khu), không còn cấp huyện.",mn:"Ban thường vụ bầu trong số uỷ viên cấp uỷ; bí thư và phó bí thư bầu trong số uỷ viên thường vụ.)",t:"m",q:"Hội nghị cấp uỷ địa phương (tỉnh uỷ, đảng uỷ xã) bầu ban thường vụ trong số",o:["đại biểu đại hội","uỷ viên thường vụ","uỷ viên cấp uỷ","đại biểu dự khuyết"],c:2},{id:"vb04-86",s:"",cc:"Điều 20, khoản 1 — Điều lệ Đảng.",gt:"Chủ nhiệm uỷ ban kiểm tra được bầu trong số uỷ viên uỷ ban kiểm tra.",mn:"Chủ nhiệm UBKTT bầu trong số uỷ viên uỷ ban kiểm tra - lãnh đạo UBKT thì lấy từ chính UBKT.",t:"m",q:"Cấp uỷ địa phương bầu chủ nhiệm uỷ ban kiểm tra trong số",o:["uỷ viên ban thường vụ","uỷ viên uỷ ban kiểm tra","uỷ viên cấp uỷ","phó bí thư"],c:1},{id:"vb04-87",s:"",cc:"Điều 20, khoản 3 - Điều lệ Đảng.",gt:"Ban thường vụ lãnh đạo và kiểm tra việc thực hiện nghị quyết của đại hội, cấp uỷ cùng cấp và cấp trên.",mn:'Ban thường vụ kiểm tra nghị quyết của đại hội, cấp uỷ cùng cấp và cấp trên - nhớ "cùng cấp + cấp trên”.',t:"m",q:"Ban thường vụ có nhiệm vụ lãnh đạo và kiểm tra việc thực hiện nghị quyết của đại hội đại biểu, nghị quyết, chỉ thị của",o:["cấp uỷ cùng cấp và cấp trên","Bộ Chính trị và Ban Bí thư","Ban Chấp hành Trung ương","Đại hội đại biểu toàn quốc"],c:0},{id:"vb04-88",s:"",cc:"Điều 20, khoản 4 — Điều lệ Đảng.",gt:"Thường trực cấp uỷ gồm bí thư, các phó bí thư chỉ đạo kiểm tra việc thực hiện nghị quyết, chỉ thị của cấp uỷ, ban thường vụ và cấp uỷ cấp trên.",mn:"Thường trực (bí thư + phó bí thư) lo nghị quyết, chỉ thị của cấp uỷ, ban thường vụ và cấp uỷ cấp trên + việc hằng ngày. lưác nghiệm Điều lệ Đảng - Trang đa",t:"m",q:"Thường trực cấp uỷ gồm bí thư và các phó bí thư có trách nhiệm chỉ đạo kiểm tra việc thực hiện và giải quyết công việc hằng ngày của đảng bộ.",o:["nghị quyết, chỉ thị của cấp uỷ, ban thường vụ và cấp uỷ cấp trên","quy định của Bộ Chính trị","các kế hoạch của địa phương","nghị quyết của Ban Bí thư"],c:0},{id:"vb04-89",s:"",cc:"Điều 18, khoản 1 — Điều lệ Đảng Cộng sản Việt Nam (Đại hội XI, 2011).",gt:"Đại hội đảng bộ cấp tỉnh được triệu tập thường lệ 5 năm một lần, có thể sớm hoặc muộn hơn nhưng không quá 1 năm.",mn:"Chốt đúng: 5 năm/lần, lệch không quá 1 năm ~ loại 4 năm, 6 năm.",t:"m",q:"Khẳng định nào sau đây là đúng về thời gian triệu tập đại hội đảng bộ cấp tỉnh, thành phố trực thuộc Trung ương?",o:["Triệu tập thường lệ 4 năm một lần.","Triệu tập thường lệ 5 năm một lần, có thể sớm hoặc muộn hơn nhưng không quá 1 năm.","Triệu tập thường lệ 6 năm một lần, có thể lùi tối đa 2 năm.","Triệu tập khi Ban Chấp hành Trung ương yêu cầu."],c:1},{id:"vb04-90",s:"",cc:"Điều 18, khoản 2 - Điều lệ láng.",gt:"Cả 3 nhiệm vụ trên đều thuộc thẩm quyền của đại hội đảng bộ cấp tỉnh, cấp xã..=] Cập nhật: theo mô hình tổ chức đảng 2 cấp (QĐ 20-QĐ/TW năm 2026), cấp địa phương gồm cấp tỉnh và cấp xã (xã, phường, đặc khu), không còn cấp huyện.",mn:"Thảo luận văn kiện + đánh giá nhiệm kỳ + bầu cử cảáA, B, C đều đúng (D).",t:"m",q:"Đại hội đại biểu đảng bộ địa phương (cấp tỉnh, cấp xã) có nhiệm vụ:",o:["Thảo luận văn kiện của cấp uỷ cấp trên.","Đánh giá kết quả thực hiện nghị quyết nhiệm kỳ vừa qua.","Bầu cấp uỷ và đại biểu dự đại hội cấp trên.","Cả A, B, C đều đúng."],c:3},{id:"vb04-91",s:"",cc:"Điều 18, khoản 3 — Điều lệ Đảng.",gt:"Khi có trên một nửa số cấp uỷ trực thuộc yêu cầu và được cấp trên đồng ý, cấp uỷ được triệu tập đại hội bất thường. ¬",mn:"Bất thường cần trên một nửa cấp uỷ yêu cầu - không phải 1/3 hay 2/3.",t:"m",q:"Đại hội đại biểu bất thường ở cấp địa phương được triệu tập khi có trên số cấp uỷ trực thuộc yêu cầu và được cấp uỷ cấp trên trực tiếp đồng ý.",o:["một phần ba","một nửa","hai phần ba","ba phân tư"],c:1},{id:"vb04-92",s:"",cc:"Điều 18, khoản 3 — Điều lệ Động.",gt:"Cấp uỷ địa phương không được tự ý triệu tập đại hội nếu không có sự đồng ý của cấp trên trực tiếp.",mn:'Sai là câu “tự ý quyết định" (A) — luôn cần cấp trên trực tiếp đồng ý.',t:"m",q:"Khẳng định nào sau đây là sai theo Điều lệ Đảng?",o:["Cấp uỷ địa phương có thế tự ý quyết định thời gian đại hội khi thấy cần.","Cấp uỷ địa phương được triệu tập đại hội bất thường nếu được cấp trên trực tiếp đồng ý.","Đại biểu dự đại hội bất thường phải là cấp uỷ viên đương nhiệm và đủ tư cách.","Cấp uỷ các cấp lãnh đạo thực hiện nghị quyết đại hội đại biểu và chỉ thị của cấp trên."],c:0},{id:"vb04-93",s:"",cc:"Điều I9, khoản Ì- Điều lệ Động.",gt:"Cấp uỷ địa phương lãnh đạo thực hiện nghị quyết đại hội đại biểu và các nghị quyết, chỉ thị của cấp trên.",mn:"Lãnh đạo thực hiện nghị quyết đại hội và chỉ thị cấp trên. - cả A và B (D); không phải nghị quyết Quốc hội.",t:"m",q:"Cấp uỷ địa phương lãnh đạo thực hiện các nhiệm vụ sau đây:",o:["Thực hiện nghị quyết đại hội đại biểu.","Thực hiện nghị quyết, chỉ thị của cấp trên.","Thực hiện các nghị quyết của Quốc hội.","Cả A và B đều đúng."],c:3},{id:"vb04-94",s:"",cc:"Điều 19, khoản 2 — Điều lệ Đảng.",gt:"Hội nghị cấp uỷ địa phương do Ban Thường vụ triệu tập thường lệ 3 tháng một lần. __] Cập nhật: theo mô hình tổ chức đảng 2 cấp (QĐÐ 20-QĐ/TW năm 2026), cấp địa phương gồm cấp tỉnh và cấp xã (xã, phường, đặc khu), không còn cấp huyện.",mn:"Định kỷ 3 tháng/lần - ging cầu hội nghị cấp uỷ, môi quý một lần.",t:"m",q:"Hội nghị cấp uỷ địa phương (tỉnh uỷ, đảng uỷ xã) do Ban Thường vụ triệu tập định kỳ một lần.",o:["ba tháng","sáu tháng","chín tháng","một năm"],c:0},{id:"vb04-95",s:"",cc:"Điều 20, khoản 1 — Điều lệ Đảng.",gt:"Hội nghị cấp uỷ các cấp bầu Ban Thường vụ, Bí thư, Phó Bí thư, Ủy ban Kiểm tra và Chủ nhiệm Ủy ban Kiểm tra.",mn:"Bầu cả BTV, bí thư/phó bí thư, UBKT và chủ nhiệm UBKT ¬„ cảáA, B, Gc(D).",t:"m",q:"Hội nghị cấp uỷ các cấp có quyền bầu những cơ quan nào sau đây?",o:["Ban Thường vụ","Bí thư, Phó Bí thư","Ủy ban Kiểm tra và Chủ nhiệm Ủy ban Kiểm tra","GCảA,B,C đều đúng"],c:3},{id:"vb04-96",s:"",cc:"Điều 20, khoản 3 - Điều lệ Đảng.",gt:"Tất cả các nội dung trên đều là nhiệm vụ của Ban Thường vụ cấp uỷ.",mn:"BTV vừa lãnh đạo - kiểm tra, vừa quyết chủ trương - cán bộ, vừa lo kỳ họp ›- cảÄA,B,C (D).",t:"m",q:"Ban Thường vụ có nhiệm vụ chủ yếu là:",o:["Lãnh đạo, kiểm tra việc thực hiện nghị quyết của đại hội đại biểu.","Quyết định các vấn đề về chủ trương, tổ chức, cán bộ.","Triệu tập và chuẩn bị nội dung các kỳ họp cấp uỷ.","Cả A, B, C đều đúng."],c:3},{id:"vb04-97",s:"",cc:"Điều 20, khoản 4 - Điều lệ Đảng.",gt:"Thường trực cấp uỷ gồm Bí thư và các Phó Bí thư, chịu trách nhiệm chỉ đạo công việc hằng ngày của đảng bộ. ¬",mn:"Thường trực chỉ gồm bí thư + các phó bí thư — không có UBKT hay uỷ viên thường vụ.",t:"m",q:"Thường trực cấp uỷ gồm các chức danh nào sau đây?",o:["Bí thư, các Phó Bí thư","Bí thư, Phó Bí thư, Chủ nhiệm Ủy ban Kiểm tra","Bí thư, Phó Bí thư, Ủy viên Thường vụ","Bí thư, Phó Bí thư, Ủy viên Ban Chấp hành"],c:0},{id:"vb04-98",s:"",cc:"Điều 20, khoản 4 - Điều lệ Đảng.",gt:"Thường trực cấp uỷ gồm Bí thư, các Phó Bí thư, có nhiệm vụ chỉ đạo kiểm tra, giải quyết công việc hằng ngày và chuẩn bị nội dung hợp ban thường vụ.",mn:"Thường trực vừa chỉ đạo kiểm tra, vừa giải quyết việc hằng ngày, vừa chuẩn bị họp BTV ~„ cảA,B,C (D). Chương V: TỔ CHỨC CƠ SỞ ĐẢNG",t:"m",q:"Khẳng định nào sau đây là đúng về nhiệm vụ của Thường trực cấp uỷ?",o:["Chỉ đạo kiểm tra việc thực hiện nghị quyết, chỉ thị của cấp uỷ và ban thường vụ.","Giải quyết công việc hằng ngày của đảng bộ.","Chuẩn bị nội dung các kỳ họp của ban thường vụ.","Cả A, B, C đều đúng."],c:3},{id:"vb04-99",s:"",cc:"Điều 21. khoản 1 - Điều lệ Đảng.",gt:"Tổ chức cơ sở đảng là nền tảng của Đảng, là hạt nhân chính trị ở cơ sở.",mn:"TCCS đáng = “nền tảng của Đảng, hạt nhân chính trị ở cơ sở” — nhớ 2 cụm “nền tảng” + “hạt nhân”.",t:"m",q:"Tổ chức cơ sở đảng là gì đối với Đảng Cộng sản Việt Nam?",o:["Là cấp chỉ đạo trung gian.","Là nền tảng của Đảng, hạt nhân chính trị ở cơ sở.","Là bộ phận hành chính của Đảng.","Là tổ chức trực thuộc Trung ương."],c:1},{id:"vb04-100",s:"",cc:"Điều 21, khoản 2 — Điều lệ Đảng.",gt:"Từ 3 đảng viên chính thức trở lên được lập tổ chức cơ sở đảng.",mn:"Từ 3 đảng viên chính thức trở lên là lập được tổ chức cơ sở đảng — khác so 3.",t:"m",q:"Ở xã, phường, thị trấn có từ bao nhiêu đảng viên chính thức trở lên thì được lập tổ chức cơ sở đảng?",o:["2 đảng viên.","3 đảng viên.","5 đảng viên.","7 đảng viên."],c:1},{id:"vb04-101",s:"",cc:"Điều 21, khoản 2 — Điều lệ Đảng.",gt:"Cấp uỷ cấp trên trực tiếp giới thiệu đảng viên sinh hoạt tại tổ chức cơ sở đảng thích hợp.",mn:"Chưa đủ 3 thì cấp trên giới thiệu đảng viên sinh hoạt ở tổ chức cơ sở đảng thích hợp (không để đảng viên “mô côi” sinh hoạt).",t:"m",q:"Nếu chưa đủ 3 đảng viên chính thức, cấp uỷ cấp trên trực tiếp có trách nhiệm gì?",o:["Chưa được lập chi bộ.","Giới thiệu đảng viên sinh hoạt ở tổ chức cơ sở đảng thích hợp.","Tạm thời ghép sinh hoạt ở cấp trên.","Xin ý kiến Ban Tổ chức Trung ương."],c:1},{id:"vb04-102",s:"",cc:"Điều 21, khoản 3 ~ Điều lệ Đảng.",gt:"Dưới 30 đảng viên, lập chi bộ cơ sở.",mn:"Dưới 30 đảng viên „ lập chi bộ cơ sở.",t:"m",q:"Tổ chức cơ sở đảng dưới 30 đảng viên được lập thành:",o:["Đảng bộ cơ sở.","Chi bộ cơ sở.","Chi bộ trực thuộc.","Tổ đảng."],c:1},{id:"vb04-103",s:"",cc:"Điều 21, khoản 4 — Điều lệ Đảng.",gt:"Từ 30 đảng viên trở lên lập đảng bộ cơ sở.",mn:"Từ 30 đảng viên trở lên. lập đảng bộ cơ sở. Cấp với câu trên: mốc 30 phân định chỉ bộ.„ đảng bộ.",t:"m",q:"Tổ chức cơ sở đảng có từ 30 đảng viên trở lên sẽ lập:",o:["Chi bộ trực thuộc.","Đảng bộ cơ sở.","Đảng bộ bộ phận.","Tổ đảng."],c:1},{id:"vb04-104",s:"",cc:"Điều 21, khoản 5 - Điều lệ Đảng.",gt:"Cấp dưới phải báo cáo và được cấp uỷ cấp trên trực tiếp đồng ý.",mn:"Lập đảng bộ khi chưa đủ 30 thì phải báo cáo và được cấp uỷ cấp trên trực tiếp đồng ý.",t:"m",q:"Trường hợp lập đảng bộ cơ sở khi chưa đủ 30 đảng viên phải:",o:["Báo cáo và được cấp uỷ cấp trên trực tiếp đồng ý.","Xin ý kiến Bộ Chính trị.","Có nghị quyết chỉ bộ.","Do đảng viên biểu quyết."],c:0},{id:"vb04-105",s:"",cc:"Điều 22, khoản 1 Điều lệ Đảng.",gt:"Đại hội cơ sở đang tổ chức 5 năm một lần.",mn:"Đại hội tổ chức cơ sở đảng: 5 năm một lần.",t:"m",q:"Đại hội tổ chức cơ sở đảng được triệu tập định kỳ:",o:["3năm một lần.","4 năm một lần.","5 năm một lần.","10 năm một lần."],c:2},{id:"vb04-106",s:"",cc:"Điều 22, khoản 1 — Điều lệ Đảng.",gt:"Có thể sớm hoặc muộn hơn, nhưng không quá 1 năm.",mn:"Có thể sớm/muộn hơn nhưng không quá 1 năm.",t:"m",q:"Thời gian triệu tập đại hội cơ sở đảng có thế sớm hoặc muộn hơn, nhưng không quá:",o:["3tháng.","6tháng.","1năm.","2năm."],c:2},{id:"vb04-107",s:"",cc:"Điều 22, khoản 3 — Điều lệ Đảng.",gt:"Khi có trên 1⁄4 số tổ chức đảng trực thuộc yêu cầu và được cấp trên đồng ý.",mn:"Đại hội bất thường = trên 1⁄4 số tổ chức đảng trực thuộc yêu cầu và được cấp trên đồng ý (đủ 2 về).",t:"m",q:"Điều kiện triệu tập đại hội đảng viên bất thường là:",o:["Khi có yêu cầu của cấp trên.","Khi có hơn một nửa số tổ chức đảng trực thuộc yêu cầu và được cấp trên đồng ý.","Khi bí thư chi bộ đề nghị.","Khi đảng viên chỉ bộ yêu cầu."],c:1},{id:"vb04-108",s:"",cc:"liêu 22, khoản 4 ~ Điều lệ Đảng.",gt:"Đảng uỷ, chi uỷ cơ sở họp thường lệ mỗi tháng một lần.",mn:"Đảng uỷ, chi uỷ cơ sở họp thường lệ mỗi tháng một lần.",t:"m",q:"Đảng uỷ, chi uỷ cơ sở họp thường lệ với tần suất:",o:["3 tháng/lần.","2 tháng/lần.","Mỗi tháng 1 lần.","6tháng/lần."],c:2},{id:"vb04-109",s:"",cc:"Điều 22, khoản 5 = Điều lệ Đảng.",gt:"Đảng uỷ cơ sở có từ 9 uỷ viên trở lên phải bầu Ban Thường vụ.",mn:"Đảng uỷ cơ sở tự 9 uỷ viên trở lên _. bầu Ban Thường vụ. Nhớ ngưỡng 9.",t:"m",q:"Đảng uỷ cơ sở có từ 9 uỷ viên trở lên phải bầu:",o:["Ban Thường vụ.","Ủy ban Kiểm tra.","Bí thư và Phó bí thư.","Đại hội đại biểu."],c:0},{id:"vb04-110",s:"",cc:"Điều 22, khoản 6 — Điều lệ Đảng.",gt:"Chi bộ cơ sở họp thường lệ mỗi tháng một lần.",mn:"Chi bộ cơ sở cũng họp thường lệ mỗi tháng một lần (giống đảng uỷ/chi uỷ).",t:"m",q:"Chi bộ cơ sở họp thường lệ với tần suất bao lâu một lần?",o:["Hằng tuần.","Mỗi tháng một lần.","Ba tháng một lần.","Sáu tháng một lần."],c:1},{id:"vb04-111",s:"",cc:"Điều 23, khoản 1 - Điều lộ Đáng.",gt:"Đây là nhiệm vụ chính trị cơ bản của tổ chức cơ sở đảng.",mn:"Nhiệm vụ chính trị cơ bản = chấp hành đường lối, chính sách của Đảng và pháp luật Nhà nước.",t:"m",q:"Một trong các nhiệm vụ quan trọng của tổ chức cơ sở đảng là:",o:["Quản lý tài chính Nhà nước.","Chấp hành đường lối, chính sách của Đảng và pháp luật Nhà nước.","Tổ chức phong trào thanh niên.","Thực hiện giám sát cộng đồng."],c:1},{id:"vb04-112",s:"",cc:"Điều 23, khoản 2 — Điều lệ Dụng.",gt:"Tổ chức cơ sở đảng thường xuyên giáo dục, rèn luyện, quản lý cán bộ, đảng viên.",mn:"TCCS đáng giáo dục, rèn luyện, quản lý cán bộ, đảng viên (không phải nhân dân hay đoàn thể).",t:"m",q:"Tổ chức cơ sở đảng có trách nhiệm giáo dục, rèn luyện, quản lý ai?",o:["Cán bộ, đảng viên.","Cán bộ Nhà nước.","Nhân dân địa phương.","Tổ chức đoàn thể."],c:0},{id:"vb04-113",s:"",cc:"Điều 23 — đoạn cuối — Điều lệ Đảng. lưác nghiện Điều lệ Đảng Trang X1",gt:"Đảng uỷ cơ sở được uỷ quyền có thể quyết định kết nạp và khai trừ đảng viên.",mn:"Khi được uỷ quyền, đảng uỷ cơ sở quyết định kết nạp và khai trừ đảng viên.",t:"m",q:"Khi được cấp trên uỷ quyền, Đảng uỷ cơ sở được quyền quyết định việc nào sau đây?",o:["Kết nạp và khai trừ đảng viên.","Kỷ luật tổ chức đảng cấp dưới.","Bổ nhiệm cán bộ chính quyền.","Triệu tập đại hội đảng bộ tỉnh."],c:0},{id:"vb04-114",s:"",cc:"Điều 24, khoản 1 — Điều lệ Đảng.",gt:"Chi bộ trực thuộc có ít nhất 3 đảng viên chính thức.",mn:"Chi bộ trực thuộc ít nhất 3 đảng viên chính thức ~ lại là còn số 3.",t:"m",q:"Mỗi chi bộ trực thuộc đảng uỷ cơ sở ít nhất phải có bao nhiêu đảng viên chính thức?",o:["2","3","5","7"],c:1},{id:"vb04-115",s:"",cc:"Điều 24, khoản 1 — Điều lệ Đảng.",gt:"Chi bộ đông đảng viên có thể chia thành nhiều tổ đảng.",mn:"Chi bộ đông đảng viên chia thành nhiều tổ đảng.",t:"m",q:"Chỉ bộ đông đảng viên có thể chia thành nhiều:",o:["Nhóm sinh hoạt.","Tổ đảng.","Tiểu ban.","Ban điều hành."],c:1},{id:"vb04-116",s:"",cc:"Điều 24, khoản 4 — Điều lệ Đảng.",gt:"Chỉ bộ có dưới 9 đảng viên bầu Bí thư, nếu cần thì bầu Phó bí thư.",mn:"Chi bộ dưới 9 đảng viên. bầu Bí thư (nếu cần thì Phó bí thư). Ngưỡng 9 lặp lại. ¬",t:"m",q:"Chi bộ có dưới 9 đảng viên chính thức thì bầu:",o:["Bí thư chi bộ (nếu cần có Phó bí thư).","Chi uỷ và Ban kiểm tra.","Ban Thường vụ.","Tổ trưởng đảng."],c:0},{id:"vb04-117",s:"",cc:"QÐ 20-QPD/TW (Mục 23.1); Điều 22 — Điều lệ Đảng.",gt:"Đại hội chỉ bộ được triệu tập 5 năm một lần. Riêng chỉ bộ trực thuộc đảng uỷ cơ sở: trước đây Điều 24 khoản 3 quy định “năm năm hai lần”, nay QÐ 20- (Q)Ð/TW (Mục 23.1) thí điểm 5 năm một lần, từ nhiệm kỳ 2025-2030.",mn:"Đại hội chỉ bộ nay 5 năm một lần (QĐ 20 thí điểm), thống nhất với đại hội tổ chức cơ sở đảng.",t:"m",q:"Đại hội chi bộ được triệu tập định kỳ bao lâu một lần?",o:["3năm.","5năm.","10năm.","2năm."],c:1},{id:"vb04-118",s:"",cc:"Điều 24, khoản 2 — Điều lệ Động.",gt:"Chi bộ lãnh đạo thực hiện nhiệm vụ chính trị, giáo dục — quản lý đảng viên, vận động quần chúng, phát triển đảng viên.",mn:"Chi bộ lo trọn gói: chính trị ~ giáo dục, quản lý đảng viên - vận động quần chúng - phát triển đảng viên. Chương VI: TỔ CHỨC ĐANG TRONG QUÂN ĐỘI NHÂN DÂN VIỆT NAM VÀ CÔNG AN NHÂN DÂN VIỆT NAM",t:"m",q:"Chỉ bộ lãnh đạo thực hiện các nhiệm vụ nào?",o:["Nhiệm vụ chính trị, giáo dục, quản lý đảng viên, công tác vận động quần chúng, phát triển đảng viên.","Quản lý hành chính địa phương.","Giám sát pháp luật và an ninh trật tự.","Lập kế hoạch tài chính cơ quan."],c:0},{id:"vb04-119",s:"",cc:"Điều 21, khoản J — Điều lệ Đảng Cộng sản Việt Nam (Đại hội XI, 2011). lưác nghiệm Điều lệ Đảng Trang do",gt:"Tổ chức cơ sở đảng là nền tảng của Đảng, là hạt nhân chính trị ở cơ sở.",mn:"Cơ sở đảng là nền tảng và là hạt nhân chính trị ở cơ sở, không phải cơ quan hành chính.",t:"m",q:"Tổ chức cơ sở đảng là nền tảng của Đảng, là ở cơ sở.",o:["hạt nhân chính trị","cơ quan hành chính","đơn vị lãnh đạo","tổ chức kiểm tra"],c:0},{id:"vb04-120",s:"",cc:"Điều 21, khoản 2 — Điều lệ Đảng.",gt:"Có từ ba đảng viên chính thức trở lên được lập tổ chức cơ sở đảng.",mn:"Xã, phường, thị trấn từ ba (3) đảng viên chính thức là lập được tổ chức cơ sở đảng.",t:"m",q:"Ở xã, phường, thị trấn có từ đảng viên chính thức trở lên được lập tổ chức cơ sở đảng.",o:["hai","ba","năm","bảy"],c:1},{id:"vb04-121",s:"",cc:"Điều 21, khoản 3 - Điều lệ Đảng.",gt:"Tổ chức cơ sở đảng dưới 30 đảng viên lập chi bộ cơ sở.",mn:'Dưới 30 đảng viên + lập chi bộ cơ sở (nhỏ thì "chi”).',t:"m",q:"Tổ chức cơ sở đảng dưới ba mươi đảng viên lập ›, có các tổ đảng trực thuộc.",o:["chỉ bộ cơ sở","đảng bộ cơ sở","chi uỷ cơ sở","chi bộ trực thuộc"],c:0},{id:"vb04-122",s:"",cc:"Điều 21, khoản 4 — Điều lệ Đảng.",gt:"Tổ chức cơ sở đảng có từ 30 đảng viên trở lên lập đảng bộ cơ sở.",mn:'Từ 30 đảng viên trở lên ¬ lập đảng bộ cơ sở (động thì "bỏ”).',t:"m",q:"Tổ chức cơ sở đảng có từ ba mươi đảng viên trở lên lập, có các chi bộ trực thuộc đảng uỷ.",o:["chi bộ cơ sở","đảng bộ cơ sở","đảng uỷ bộ phận","chi uỷ cơ sở"],c:1},{id:"vb04-123",s:"",cc:"Điều 21, khoản 5 — Điều lệ Dụng.",gt:"Phải được cấp uỷ cấp trên trực tiếp đồng ý mới được lập đảng bộ cơ sở khi chưa đủ 30 đảng viên.",mn:'Chưa đủ 30 mà muốn lập đảng bộ phải được cấp uỷ cấp trên trực tiếp đồng ý — nhớ "trên trực tiếp”.',t:"m",q:"Trường hợp lập đảng bộ cơ sở trong đơn vị chưa đủ 30 đảng viên phải được đồng ý.",o:["Ban Bí thư","Ban Tổ chức Trung ương","cấp uỷ cấp trên trực tiếp","Ban Thường vụ Tỉnh uỷ"],c:2},{id:"vb04-124",s:"",cc:"Điều 22, khoản 1 - Điều lệ Đảng.",gt:"Đại hội đại biểu hoặc đại hội đảng viên cơ sở được triệu tập thường lệ 5 năm một lần.",mn:"Đại hội có số: 5 năm một lần (chốt còn số 5).",t:"m",q:"Đại hội đảng viên của tổ chức cơ sở đảng do cấp uỷ cơ sở triệu tập thường lệ một lần.",o:["ba năm","năm năm","sáu năm","bốn năm"],c:1},{id:"vb04-125",s:"",cc:"Điều 22, khoản 4 — Điều lệ Đảng.",gt:"Đảng uỷ, chi uỷ cơ sở họp thường lệ mỗi tháng một lần. lưác nghiện Điều lệ Đảng Trang đồ",mn:"Đảng uỷ, chi uỷ cơ sở họp mỗi tháng một lần (tháng, không phải quy).",t:"m",q:"Đảng uỷ, chi uỷ cơ sở họp thường lệ một lần; họp bất thường khi cần.",o:["mỗi tuần","mỗi tháng","mỗi quý","mỗi năm"],c:1},{id:"vb04-126",s:"",cc:"Điều 22, khoản 5 -— Điều lệ Đảng.",gt:"Đảng uỷ cơ sở có từ 9 uỷ viên trở lên bầu Ban Thường vụ.",mn:"Từ 9 uỷ viên trở lên mới bầu Ban Thường vụ — nhớ số 9.",t:"m",q:"Đảng uỷ cơ sở có từ uỷ viên trở lên thì bầu Ban Thường vụ; dưới số đó chỉ bầu bí thư, phó bí thư.",o:["bảy","chín","mười","mười một"],c:1},{id:"vb04-127",s:"",cc:"Điều 23, khoản 1 — Điều lệ Đảng.",gt:"Tổ chức cơ sở đảng chấp hành đường lối, chính sách của Đảng, pháp luật của Nhà nước và đề ra chủ trương, nhiệm vụ chính trị của chi bộ, đảng bộ.",mn:"Nhiệm vụ: chấp hành đường lối, pháp luật VÀ tự đề ra chủ trương, nhiệm vụ chính trị của chi bộ, đảng bộ.",t:"m",q:"Tổ chức cơ sở đảng có nhiệm vụ chấp hành đường lối, chính sách của Đảng, pháp luật của Nhà nước và.",o:["đề ra chủ trương, nhiệm vụ chính trị của đảng bộ, chỉ bộ","giám sát tổ chức cấp trên","ban hành nghị quyết cấp tỉnh","tổ chức sinh hoạt định kỳ"],c:0},{id:"vb04-128",s:"",cc:"Điều 24, khoản 1! — Điều lệ Đảng.",gt:"Chi bộ trực thuộc đảng uỷ cơ sở được tổ chức theo nơi làm việc hoặc nơi ở của đảng viên.",mn:"Chi bộ tổ chức theo nơi làm việc hoặc nơi ở của đảng viên (2 nơi: làm -—ởi.",t:"m",q:"Chi bộ trực thuộc đảng uỷ cơ sở được tổ chức theo của đảng viên.",o:["năng lực công tác","nơi làm việc hoặc nơi ở","nguyện vọng cá nhân","đơn vị hành chính"],c:1},{id:"vb04-129",s:"",cc:"Điều 21, khoản 1 - Điều lệ Dựng Cộng sản Việt Nam (Đại hội XI, 2011).",gt:"Tổ chức cơ sở đảng vừa là nền tảng của Đảng, vừa là hạt nhân chính trị ở cơ sở. _] Cập nhật: theo mô hình tổ chức đảng 2 cấp (QĐ 20-QĐ/TW năm 2026), cấp địa phương gồm cấp tỉnh và cấp xã (xã, phường, đặc khu), không còn cấp huyện.",mn:'Vị trí cơ sở đảng = nền tảng + hạt nhân chính trị › chọn "cá A và B" (D).',t:"m",q:"Khẳng định nào sau đây là đúng về vị trí của tổ chức cơ sở đảng?",o:["Là nền tảng của Đảng.","Là hạt nhân chính trị ở cơ sở.","Là cấp trung gian giữa cấp uỷ cấp trên và chỉ bộ trực thuộc.","Cả A và B đều đúng."],c:3},{id:"vb04-130",s:"",cc:"Điều 21, khoản 2 ~ Điều lệ Đảng.",gt:"Cấp uỷ cấp trên trực tiếp xem xét, quyết định tổ chức đảng đó trực thuộc cấp uỷ nào cho phù hợp. __ ] Cập nhật: theo mô hình tổ chức đảng 2 cấp (QÐ 20- QĐÐĐ/TW năm 2026), cấp địa phương gồm cấp tỉnh và cấp xã (xã, phường, đặc khu), không còn cấp huyện.",mn:"Cơ quan, doanh nghiệp có 3 đảng viên: cấp uỷ cấp trên trực tiếp quyết định trực thuộc cấp uỷ nào cho phù hợp.",t:"m",q:"Ở cơ quan, doanh nghiệp, đơn vị sự nghiệp có từ ba đảng viên chính thức trở lên, cấp uỷ cấp trên trực tiếp cử quyền gì?",o:["Bắt buộc lập chi bộ trực thuộc đảng uỷ xã.","Xem xét, quyết định tổ chức đảng đó trực thuộc cấp uỷ nào cho phù hợp.","Phải xin ý kiến Ban Bí thư trước khi lập.","Ủy quyền cho cấp cơ sở tự quyết."],c:1},{id:"vb04-131",s:"",cc:"Điều 21, khoản 5 — Điều lệ Đảng.",gt:"Chỉ khi được cấp uỷ cấp trên trực tiếp đồng ý, mới được lập đảng bộ cơ sở trong đơn vị chưa đủ 30 đảng viên.",mn:"Dưới 30 mà lập đảng bộ: ngoại lệ duy nhất là được cấp uỷ cấp trên trực tiếp đồng ý.",t:"m",q:"Tổ chức cơ sở đảng có từ 30 đảng viên trở lên sẽ lập đảng bộ cơ sở; nếu dưới 30 đảng viên chỉ được lập chi bộ cơ sở, trừ trường hợp nào sau đây?",o:["Được Ban Tổ chức Trung ương cho phép.","Được cấp uỷ cấp trên trực tiếp đồng ý.","Do đại hội chỉ bộ quyết định.","Được cơ quan quản lý Nhà nước chấp thuận."],c:1},{id:"vb04-132",s:"",cc:"Điều 22, khoản 4-6 — Điều lệ Đảng.",gt:"Cả ba quy định trên đều chính xác theo Điều 22 của Điều lệ Đảng.",mn:"Các mốc hợp Điều 22 đều đúng _› chọn cá A, B, C (D).",t:"m",q:"Khẳng định nào sau đây là đúng về việc họp của tổ chức cơ sở đảng?",o:["Đảng uỷ, chi uỷ cơ sở họp thường lệ mỗi tháng một lần.","Đảng bộ cơ sở họp thường lệ mỗi năm hai lần.","Chỉ bộ cơ sở họp thường lệ mỗi tháng một lần.","GCảA,B,C đều đúng."],c:3},{id:"vb04-133",s:"",cc:"Điều 22, khoản 5 = Điều lệ Đảng.",gt:"Dưới 9 uỷ viên, chỉ bầu Bí thư và Phó Bí thư, không lập Ban Thường vụ.",mn:"Dưới 9 uỷ viên: không có Ban Thường vụ, chỉ bầu Bí thư và Phó Bí thư.",t:"m",q:"Đảng uỷ cơ sở có 9 uỷ viên trở lên phải bầu Ban Thường vụ; dưới 9 uỷ viên thì chỉ bầu",o:["Bí thư và Phó Bí thư","Bí thư và Ủy ban kiểm tra","Ban chấp hành mở rộng","Phó Bí thư và Chi uỷ viên"],c:0},{id:"vb04-134",s:"",cc:"Điều 23, khoản 1-4 — Điều lệ Đảng.",gt:"Tổ chức cơ sở đảng có đủ cả 3 nhiệm vụ trên - chính trị, tổ chức và quần chúng.",mn:"Nhiệm vụ cơ sở đảng gồm cả chính trị - tổ chức - quần chúng ¬. chọn tất cả (D).",t:"m",q:"Nhiệm vụ nào sau đây thuộc về tổ chức cơ sở đảng?",o:["Chấp hành đường lối, chính sách của Đảng, pháp luật của Nhà nước.","Xây dựng đảng bộ, chỉ bộ trong sạch, vững mạnh.","Liên hệ mật thiết với nhân dân, chăm lo đời sống nhân dân.","Cả A,B, C đều đúng."],c:3},{id:"vb04-135",s:"",cc:"Điều 23, đoàn cuối - Điều lệ Đảng.",gt:"Đảng uỷ cơ sở chỉ được quyền quyết định kết nạp, khai trừ đảng viên nếu được cấp trên trực tiếp ủy quyền.",mn:'Đảng uỷ cơ sở kết nạp/khai trừ chỉ khi được cấp trên trực tiếp uỷ quyền (chìa khoá: "uỷ quyền”).',t:"m",q:"Đảng uỷ cơ sở được quyền quyết định kết nạp và khai trừ đảng viên khi nào?",o:["Khi có từ 30 đảng viên trở lên.","Khi được cấp uỷ cấp trên trực tiếp uỷ quyền.","Khi được Ban Bí thư cho phép.","Khi có biểu quyết của toàn thể đảng viên."],c:1},{id:"vb04-136",s:"",cc:"Điều 24, khoản 1 — Điều lệ Đảng.",gt:"Chi bộ trực thuộc phải có ít nhất 3 đảng viên chính thức.",mn:"Mọi chi bộ trực thuộc ít nhất 3 đảng viên chính thức (giống mốc lập tổ chức cơ sở).",t:"m",q:"Chỉ bộ trực thuộc đảng uỷ cơ sở được tổ chức theo nơi làm việc hoặc nơi ở, mỗi chi bộ ít nhất có bao nhiêu đảng viên chính thức?",o:["2","3","5","7"],c:1},{id:"vb04-137",s:"",cc:"Điều 24, khoản 4 = Điều lệ Đảng.",gt:"Chi bộ có dưới 9 đảng viên chỉ bầu Bí thư, nếu cần thì bầu thêm Phó Bí thư.",mn:"Chỉ bộ dưới 9 đảng viên chỉ bầu Bí thư và Phó Bí thư (số 9 lặp lại như đảng uỷ).",t:"m",q:"Chỉ bộ có dưới 9 đảng viên chính thức thì bầu các chức danh nào?",o:["Bí thư và Phó Bí thư","Bí thư, Phó Bí thư, Chi uỷ viên","Chỉ bầu Bí thư","Bí thư và Ban kiểm tra chi bộ"],c:0},{id:"vb04-138",s:"",cc:"Điều 24, khoản 2 - Điều lệ Đảng.",gt:"Chi bộ không phải cơ quan ban hành chủ trương, chính sách cấp xã mà chỉ lãnh đạo, triển khai nhiệm vụ chính trị của đơn vị.",mn:"Chi bộ KHÔNG ban hành chủ trương, chính sách cấp xã — chỉ lãnh đạo, triển khai nhiệm vụ đơn vị (đáp án sai là B). Chương VII: CÔNG TÁC KIỂM TRA, GIÁM SÁT CỦA ĐẢNG VÀ ỦY BAN KIỂM TRA CÁC CẤP",t:"m",q:"Khẳng định nào sau đây là sai về nhiệm vụ của chi bộ trực thuộc đảng uỷ cơ sở?",o:["Lãnh đạo thực hiện nhiệm vụ chính trị của đơn vị.","Là cơ quan ban hành chủ trương, chính sách cấp xã.","Làm công tác giáo dục, quản lý, phân công công tác cho đảng viên.","Kiểm tra, giám sát thi hành kỷ luật đảng viên."],c:1},{id:"vb04-139",s:"",cc:"Điều 30, khoản 1 — Điều lệ láng Cộng sản Việt Nam (Đại hội XI, 2011).",gt:"Kiểm tra, giám sát là những chức năng lãnh đạo của Đảng.",mn:"Kiểm tra, giám sát không phải việc vặt mà là chức năng lãnh đạo của Đảng. Nhớ: lãnh đạo thì phải kiểm tra.",t:"m",q:"Kiểm tra, giám sát là những của Đảng.",o:["nguyên tắc sinh hoạt","nhiệm vụ thường xuyên","chức năng lãnh đạo","công cụ quản lý"],c:2},{id:"vb04-140",s:"",cc:"Điều 30, khoản 1 — Điều lệ Đảng.",gt:"Tổ chức đảng và đảng viên chịu sự kiểm tra, giám sát của Đảng.",mn:'Tổ chức đảng và đảng viên đều phải chịu sự kiểm tra và giám sát. Cấp đối "kiểm tra — giám sát" luôn đi cùng nhau.',t:"m",q:"Tổ chức đảng và đảng viên chịu sự của Đảng.",o:["chỉ đạo và lãnh đạo","kiểm tra và giám sát","kỷ luật và phân công","biểu quyết và phê duyệt"],c:1},{id:"vb04-141",s:"",cc:"Điều 30, khoản 2 - Điều lệ Đảng.",gt:"Các cấp uỷ lãnh đạo công tác kiểm tra, giám sát các tổ chức đảng và đảng viên chấp hành Cương lĩnh, Điều lệ, nghị quyết, chỉ thị của Đảng.",mn:"Cấp uỷ lãnh đạo kiểm tra, giám sát tổ chức đảng cấp dưới và đảng viên - trong nội bộ Đảng, không phải công chức hay đoàn thể.",t:"m",q:"Các cấp uỷ đảng có trách nhiệm lãnh đạo công tác kiểm tra, giám sát đối với đối tượng nào?",o:["Tổ chức đảng cấp dưới và đảng viên.","Cán bộ công chức Nhà nước.","Các tổ chức đoàn thể chính trị - xã hội.","Cấp uỷ cấp trên."],c:0},{id:"vb04-142",s:"",cc:"Điều 31, khoản 1 — Điều lệ Đảng.",gt:"Ủy ban kiểm tra các cấp do cấp uỷ cùng cấp bầu ra.",mn:'Ủy ban kiểm tra do cấp uỷ cùng cấp bầu ra - "cùng cấp" đề ra "cùng cấp".',t:"m",q:"Ủy ban kiểm tra các cấp do ai bầu ra?",o:["Cấp uỷ cùng cấp.","Đại hội đảng viên.","Ban Thường vụ cấp trên.","Ủy ban kiểm tra cấp trên."],c:0},{id:"vb04-143",s:"",cc:"Điều 31, khoản 3 — Điều lệ Đảng.",gt:"Ủy ban kiểm tra làm việc theo chế độ tập thể, dưới sự lãnh đạo của cấp uỷ cùng cấp.",mn:"UBKT làm việc theo chế độ tập thể (không phải tập trung dân chủ), dưới sự lãnh đạo của cấp uỷ cùng cấp.",t:"m",q:"Ủy ban kiểm tra làm việc theo chế độ nào?",o:["Tập trung dân chủ","Tập thể","Cấp trên chỉ đạo, cá nhân phụ trách","Tự quản độc lập"],c:1},{id:"vb04-144",s:"",cc:"Điều 3Ì, khoản 1 - Điều lệ Dụng.",gt:"Ủy ban kiểm tra gồm một số đồng chí trong cấp uỷ và một số đồng chí ngoài cấp uỷ.",mn:"Thành phần UBKT: có người trong cấp uỷ + ngoài cấp uỷ - vừa trong vừa ngoài, không chỉ một phía.",t:"m",q:"Khẳng định nào sau đây là đúng về thành phần Ủy ban kiểm tra?",o:["Chỉ gồm các đồng chí trong cấp uỷ.","Gồm cả uỷ viên cấp uỷ và ngoài cấp uỷ.","Gồm toàn bộ đảng viên trong cơ quan kiểm tra.","Chỉ gồm các đồng chí được cấp uỷ cấp trên chỉ định."],c:1},{id:"vb04-145",s:"",cc:"Điều 31, khoản 2 - Điều lệ Đảng.",gt:"Các thành viên, chủ nhiệm, phó chủ nhiệm Ủy ban kiểm tra cấp dưới phải được cấp uỷ cấp trên trực tiếp chuẩn y.",mn:"Chủ nhiệm, phó chủ nhiệm UBKTT cấp dưới do cấp uỷ cấp trên trực tiếp chuẩn y - trên trực tiếp gật đầu.",t:"m",q:"Chủ nhiệm, phó chủ nhiệm Ủy ban kiểm tra cấp dưới phải được ai chuẩn y?",o:["Ban Tổ chức Trung ương","Cấp uỷ cấp trên trực tiếp","Bộ Chính trị","Ủy ban kiểm tra cấp trên"],c:1},{id:"vb04-146",s:"",cc:"Điều 32, khoản 1 — Điều lệ Đảng. lưác nghiện) Điều lệ Đảng Trang ó2",gt:"Ủy ban kiểm tra kiểm tra đảng viên, kể cả cấp uỷ viên cùng cấp khi có dấu hiệu vi phạm tiêu chuẩn đảng viên hoặc nhiệm vụ đảng viên.",mn:'Kiểm tra đảng viên khi có dấu hiệu vi phạm tiêu chuẩn hoặc nhiệm vụ đảng viên. Từ khoá: "dấu hiệu vi phạm”.',t:"m",q:"Ủy ban kiểm tra có nhiệm vụ kiểm tra đảng viên khi có dấu hiệu gì?",o:["Suy thoái tư tưởng chính trị","Vi phạm tiêu chuẩn đảng viên hoặc nhiệm vụ đảng viên","Không hoàn thành chỉ tiêu công tác","Vi phạm quy chế sinh hoạt chi bộ"],c:1},{id:"vb04-147",s:"",cc:"Điều 32, khoản 2 — Điều lệ Đảng.",gt:"Ủy ban kiểm tra kiểm tra tổ chức đảng cấp dưới khi có dấu hiệu vi phạm Điều lệ, Cương lĩnh, nghị quyết, chỉ thị của Đảng.",mn:'Kiểm tra tổ chức đảng cấp dưới khi có dấu hiệu vi phạm Điều lệ, Cương lĩnh, nghị quyết, chỉ thị - văn là "dấu hiệu vi phạm”.',t:"m",q:"Ủy ban kiểm tra có quyền kiểm tra tổ chức đảng cấp dưới trong những trường hợp nào sau đây?",o:["Khi có dấu hiệu vi phạm Điều lệ, nghị quyết, chỉ thị của Đảng.","Khi tổ chức đó có báo cáo tài chính sai lệch.","Khi được yêu cầu của cơ quan Nhà nước.","Khi có đề nghị từ Ban Bí thư."],c:0},{id:"vb04-148",s:"",cc:"Điều 32, khoản 3 — Điều lệ Đảng.",gt:"Ủy ban kiểm tra giám sát cả cấp uỷ viên cùng cấp, cán bộ diện cấp uỷ quản lý và tổ chức đảng cấp dưới.",mn:"Giám sát của UBKT bao trùm: cấp uỷ viên cùng cấp, cán bộ diện cấp uỷ quản lý, tổ chức đảng cấp dưới -› cả A, B, C đều đúng.",t:"m",q:"Khảng định nào sau đây là đúng về công tác giám sát của Ủy ban kiểm tra?",o:["Giám sát cấp uỷ viên cùng cấp, cán bộ diện cấp uỷ cùng cấp quản lý.","Giám sát tổ chức đảng cấp dưới.","Giám sát việc thực hiện chủ trương, đường lối, chính sách của Đảng.","Cả A, B,C đều đúng."],c:3},{id:"vb04-149",s:"",cc:"Điều 33- Điều lệ Đảng.",gt:"Ủy ban kiểm tra có quyền yêu cầu tổ chức đảng cấp dưới và đảng viên cung cấp tài liệu liên quan đến nội dung kiểm tra.",mn:"Khi kiểm tra, UBKT được quyền yêu cầu báo cáo, cung cấp tài liệu — chỉ thu thập, không tự ra kỷ luật.",t:"m",q:"Ủy ban kiểm tra có quyền gì trong quá trình thực hiện nhiệm vụ kiểm tra?",o:["Yêu cầu tổ chức đảng cấp dưới và đảng viên báo cáo, cung cấp tài liệu liên quan.","Tự mình ra quyết định kỷ luật.","Đình chỉ sinh hoạt đảng viên vi phạm.","Thay đổi nhân sự trong cấp uỷ cấp dưới."],c:0},{id:"vb04-150",s:"",cc:"Điều 32, khoản 4 - Điều lệ Đảng.",gt:"Ủy ban kiểm tra xem xét, kết luận và đề nghị thi hành kỷ luật đối với tổ chức, cá nhân vi phạm.",mn:"UBKT xem xét, kết luận rồi đề nghị thi hành kỷ luật - đề nghị chủ không tự quyết luân chuyển hay bồi thường.",t:"m",q:"Ủy ban kiểm tra các cấp có quyền xem xét, kết luận và đề nghị cấp uỷ thi hành khi phát hiện vi phạm.",o:["kỷ luật","bồi thường","kiểm điểm","luân chuyển"],c:0},{id:"vb04-151",s:"",cc:"Điều 32, khoản 5 — Điều lệ Đảng.",gt:"Ủy ban kiểm tra giải quyết tố cáo đối với tổ chức đảng, đảng viên và khiếu nại về kỷ luật Đảng.",mn:"UBKT giải quyết tố cáo tổ chức đảng, đảng viên + khiếu nại về kỷ luật Đảng - trong Đảng, không phải khiếu nại hành chính, dân sự.",t:"m",q:"Ủy ban kiểm tra có nhiệm vụ giải quyết các loại đơn thư nào?",o:["Khiếu nại về kỷ luật Đảng và tố cáo đối với tổ chức đảng, đảng viên.","Khiếu nại hành chính và khiếu kiện dân sự.","Tố cáo về tài sản cá nhân đảng viên.","Khiếu nại về kết quả bầu cử đại biểu."],c:0},{id:"vb04-152",s:"",cc:"Điều 32, khoản 6 = Điều lệ Đảng.",gt:"Ủy ban kiểm tra kiểm tra tài chính của cấp uỷ cấp dưới và cơ quan tài chính cấp uỷ cùng cấp.",mn:"Kiểm tra tài chính: cấp uỷ cấp dưới + cơ quan tài chính cấp uỷ cùng cấp - dưới và cùng cấp, không ra ngoài chính quyền, đoàn thể.",t:"m",q:"Ủy ban kiểm tra các cấp có nhiệm vụ kiểm tra tài chính của đối tượng nào?",o:["Cấp uỷ cấp dưới và cơ quan tài chính cấp uỷ cùng cấp.","Mặt trận Tổ quốc và các đoàn thể.","Các đơn vị kinh tế của Đảng.","Chính quyền địa phương."],c:0},{id:"vb04-153",s:"",cc:"liệu 31, 33 ~ Điều lệ Đảng,",gt:"Ủy ban kiểm tra không có quyền ra nghị quyết chỉ đạo các cấp uỷ khác, chỉ hoạt động theo sự lãnh đạo của cấp uỷ cùng cấp.",mn:"Câu SAI: UBKT không có quyền ra nghị quyết chỉ đạo cấp uỷ khác - nó dưới sự lãnh đạo của cấp uỷ, không đúng trên chỉ đạo ai. Chương VIII: KHEN THƯỞỚNG VÀ KỶ LUẬT",t:"m",q:"Khẳng định nào sau đây là sai về thẩm quyền của Ủy ban kiểm tra?",o:["Có quyền yêu cầu báo cáo, cung cấp tài liệu.","Có quyền ra nghị quyết chỉ đạo các cấp uỷ khác.","Làm việc theo chế độ tập thể.","Dưới sự lãnh đạo của cấp uỷ cùng cấp."],c:1},{id:"vb04-154",s:"",cc:"Điều 34 - Điều lệ Đảng Cộng sản Việt Nam.",gt:"Việc khen thưởng tổ chức đảng và đảng viên do Ban Chấp hành Trung ương quy định.",mn:"Khen thưởng tổ chức đảng và đảng viên do Ban Chấp hành Trung ương quy định. Nhớ: cấp cao nhất, họp toàn thể là BCH Trung ương đặt ra luật chơi khen thưởng. ¬",t:"m",q:"Tổ chức đảng và đảng viên có thành tích được khen thưởng theo quy định của cơ quan nào?",o:["Bộ Chính trị","Ban Tổ chức Trung ương","Ban Chấp hành Trung ương","Ủy ban Kiểm tra Trung ương"],c:2},{id:"vb04-155",s:"",cc:"Điều 35, khoản 1 — Điều lệ Đảng.",gt:"Đảng quy định việc xử lý kỷ luật phải công minh, chính xác, kịp thời.",mn:'Nguyên tắc kỷ luật: Công minh — Chính xác - Kịp thời (“Công - Chính - Kịp"). Nhớ 3 chữ dấu C-C-K.',t:"m",q:"Kỷ luật trong Đảng phải bảo đảm nguyên tắc nào sau đây?",o:["Công minh, chính xác, kịp thời.","Nghiêm khác, tuyệt đối, nhanh chóng.","Dân chủ, công khai, tập trung.","Đúng người, đúng tội, đúng thời điểm."],c:0},{id:"vb04-156",s:"",cc:"Điều 35, khoản 2 Điều lệ Đảng.",gt:"Đảng viên chính thức có thể bị kỷ luật đến mức cao nhất là khai trừ.",mn:'Đảng viên chính thức — mức cao nhất là Khai trừ. Chính thức mới bị "dưới" hẳn khỏi Đảng.',t:"m",q:"Hình thức kỷ luật cao nhất đối với đảng viên chính thức là:",o:["Khiển trách.","Cảnh cáo.","Cách chức.","Khai trừ."],c:3},{id:"vb04-157",s:"",cc:"Điều 35, khoản 2 - Điều lệ Đảng.",gt:"Đảng viên dự bị chỉ bị kỷ luật ở mức khiển trách hoặc cảnh cáo, không bị khai trừ.",mn:"Đảng viên dự bị cao nhất chỉ tới Cảnh cáo — chưa chính thức nên không bị khai trừ. Dự bị: Khiển trách/Cảnh cáo. lưác nghiện Điều lệ Đảng Trang 3Ù",t:"m",q:"Đối với đảng viên dự bị, hình thức kỷ luật cao nhất là:",o:["Khiển trách.","Cảnh cáo.","Khai trừ.","Cách chức."],c:1},{id:"vb04-158",s:"",cc:"Điều 36, khoản 1 -— Điều lệ Đảng.",gt:"Chi bộ có quyền khiển trách, cảnh cáo đảng viên vi phạm phẩm chất chính trị, tư tưởng, đạo đức, lối sống..~ ] Cập nhật: theo mô hình tổ chức đảng 2 cấp (QÐ 20-()Ð/TW năm 2026), cấp địa phương gồm cấp tỉnh và cấp xã (xã, phường, đặc khu), không còn cấp huyện.",mn:'Vi phạm phẩm chất, đạo đức, lối sống trong chỉ bộ thì Chỉ bộ tự quyết. Nhớ: "của nhà nào nhà nấy xử" - Chỉ bộ.',t:"m",q:"Cấp uỷ nào có thẩm quyền quyết định kỷ luật đảng viên vi phạm phẩm chất chính trị, đạo đức, lối sống trong chỉ bộ?",o:["Cấp uỷ cấp trên trực tiếp.","Chi bộ.","Ban Thường vụ cấp uỷ cấp trên.","Ủy ban kiểm tra."],c:1},{id:"vb04-159",s:"",cc:"Điều 36, khoản 1 — Điều lệ Đảng.",gt:"Đảng uỷ cơ sở được uỷ quyền kết nạp đảng viên thì chỉ được khai trừ đảng viên không phải là cấp uỷ viên cùng cấp và không thuộc diện cấp trên quản lý.",mn:'Đảng uỷ cơ sở được uỷ quyền chỉ khai trừ được đảng viên không phải cấp uỷ viên cùng cấp và không thuộc diện cấp trên quản lý. Nhớ: chỉ đụng "lính thường", không đúng cấp uỷ.',t:"m",q:"Đảng uỷ cơ sở được uỷ quyền kết nạp đảng viên thì có quyền quyết định khai trừ đối với ai?",o:["Tất cả đảng viên trong đảng bộ.","Đảng viên không phải là cấp uỷ viên cùng cấp và không thuộc diện cấp trên quản lý.","Cấp uỷ viên cùng cấp.","Đảng viên là cán bộ thuộc diện cấp trên quản lý."],c:1},{id:"vb04-160",s:"",cc:"Điều 36, khoản 3 — Điều lệ Đảng.",gt:"Ban Chấp hành Trung ương có quyền quyết định kỷ luật cả Uỷ viên Trung ương, Bộ Chính trị, Ban Bí thư.",mn:'BCH Trung ương kỷ luật được cả Uỷ viên Trung ương, Bộ Chính trị, Ban Bí thư - chọn "Tất cả" (D). Cấp cao nhất xử được mời Uỷ viên cấp cao.',t:"m",q:"Ban Chấp hành Trung ương có quyền quyết định hình thức kỷ luật đối với ai sau đây?",o:["Ủy viên Bộ Chính trị.","Ủy viên Ban Bí thư.","Ủy viên Ban Chấp hành Trung ương.","Tất cả các trường hợp trên."],c:3},{id:"vb04-161",s:"",cc:"Điều 36, khoản 5 -— Điền lệ Đảng.",gt:"Cấp trên có quyền chuẩn y, thay đổi hoặc xoá bỏ hình thức kỷ luật do cấp dưới quyết định.",mn:'Cấp trên có 3 quyền với quyết định kỷ luật cấp dưới: Chuẩn y - Thay đổi — Xoá bỏ ("Chuẩn - Thay - Xoá").',t:"m",q:"Cấp uỷ và Ủy ban kiểm tra cấp trên có quyền gì đối với quyết định kỷ luật của cấp dưới?",o:["Chỉ được chuẩn y.","Có thế chuẩn y, thay đổi hoặc xoá bỏ hình thức kỷ luật.","Không được can thiệp.","Chỉ có quyền yêu cầu báo cáo."],c:1},{id:"vb04-162",s:"",cc:"Điều 37, khoản 2 - Điều lệ Đồng.",gt:"Kỷ luật giải tán tổ chức đảng do cấp uỷ cấp trên cách một cấp quyết định.",mn:'Giải tán tổ chức đảng do cấp uỷ cấp trên cách một cấp quyết định. Giải tán là nặng nhất nên phải "nhảy cóc" lên trên một cấp.',t:"m",q:"Tổ chức đảng bị kỷ luật giải tán do ai quyết định?",o:["Cấp uỷ cấp trên trực tiếp.","Cấp uỷ cấp trên cách một cấp.","Bộ Chính trị.","Ủy ban kiểm tra Trung ương."],c:1},{id:"vb04-163",s:"",cc:"Điều 37, khoản 3 = Điều lệ Đảng.",gt:"Tổ chức đảng chỉ bị giải tán khi chống đường lối, chính sách của Đảng hoặc vi phạm đặc biệt nghiêm trọng nguyên tắc tổ chức, sinh hoạt.",mn:'Chỉ giải tán khi chống đường lối, chính sách của Đảng hoặc vi phạm đặc biệt nghiêm trọng nguyên tắc tổ chức. Nhớ: phải "chống Đảng" hoặc "đặc biệt nghiêm trọng” mới giải tán.',t:"m",q:"Tổ chức đảng chỉ bị giải tán khi phạm vi phạm thuộc loại nào sau đây?",o:["Vi phạm nguyên tắc sinh hoạt hoặc pháp luật Nhà nước.","Có hành động chống đường lối, chính sách của Đảng hoặc vi phạm đặc biệt nghiêm trọng nguyên tắc tổ chức.","Không hoàn thành nhiệm vụ nhiều năm liên.","Không còn đủ số đảng viên sinh hoạt."],c:1},{id:"vb04-164",s:"",cc:"Điều 35, khoản 1 = Điều lệ Đảng.",gt:"Công minh thể hiện ở việc xử lý đúng người, đúng lối, không thiên vị, không phân biệt chức vụ, cấp bậc.",mn:'"Công minh" = xử nghiêm minh, không phân biệt cấp bậc. Công minh nghĩ tới "công bằng, minh bạch - ai cũng như ai”.',t:"m",q:"Nguyên tắc xử lý kỷ luật trong Đảng yêu cầu phải “công minh, chính xác, kịp thời”. Trong đó, “công minh” được hiểu là:",o:["Xử lý nghiêm minh, không phân biệt cấp bậc.","Thực hiện dân chủ, có sự giám sát của nhân dân.","Căn cứ vào vị trí công tác để giảm nhẹ hình thức.","Chỉ do cấp uỷ trực tiếp thực hiện."],c:0},{id:"vb04-165",s:"",cc:"Điều 35, khoản 2 — Điều lệ Đảng.",gt:"Hình thức “cách chức” chỉ áp dụng với đảng viên chính thức đang giữ chức vụ trong Đảng.",mn:'Cách chức chỉ áp dụng cho đảng viên chính thức có chức vụ trong Đảng. Có "chức” mới bị "cách".',t:"m",q:"Hình thức kỷ luật “cách chức” chỉ áp dụng đối với đối tượng nào?",o:["Đảng viên dự bị.","Đảng viên chính thức có chức vụ trong Đảng.","Tổ chức đảng.","Cấp uỷ viên cấp Trung ương."],c:1},{id:"vb04-166",s:"",cc:"Điều 36, khoản 1 — Điều lộ Đảng.",gt:"Chi bộ chỉ được quyết định khiển trách, cảnh cáo đảng viên trong chỉ bộ khi có vi phạm về phẩm chất chính trị, đạo đức, lối sống, sinh hoạt đảng, thực hiện nhiệm vụ đảng viên (trừ nhiệm vụ cấp trên giao).",mn:"Chi bộ xử vi phạm về phẩm chất chính trị, tư tưởng, đạo đức, lối sống, sinh hoạt đảng, nhiệm vụ đảng viên — TRỪ nhiệm vụ cấp trên giao.",t:"m",q:"Chỉ bộ có thẩm quyền xử lý những vi phạm nào của đảng viên trong chỉ bộ?",o:["Vi phạm phẩm chất chính trị, tư tưởng, đạo đức, lối sống, sinh hoạt đảng, thực hiện nhiệm vụ đảng viên.","Vi phạm nhiệm vụ do cấp trên giao.","Vi phạm kỷ luật lao động trong cơ quan.","Vi phạm pháp luật hình sự."],c:0},{id:"vb04-167",s:"",cc:"Điều 40, khoản 1 - Điều lệ Đảng,",gt:"Đảng viên bị hình phạt từ cải tạo không giam giữ trở lên phải khai trừ khỏi Đảng.",mn:'Bị án từ cải tạo không giam giữ trở lên. Khai trừ. Nhớ mốc: "cải tạo không giam giữ" là đã đủ để dưới.',t:"m",q:"Trường hợp đảng viên bị tòa án tuyên phạt “cải tạo không giam giữ”, thì hình thức kỷ luật Đảng áp dụng là:",o:["Khiển trách.","Cảnh cáo.","Khai trừ.","Tạm đình chỉ sinh hoạt đảng."],c:2},{id:"vb04-168",s:"",cc:"Điều 17, khoản 2 — Điều lệ Đảng. lưác nghiện Điều lệ Đảng Trang A0",gt:"Kỷ luật giải tán tổ chức đảng do cấp uỷ cấp trên cách một cấp quyết định, sau khi cấp trực tiếp đề nghị.",mn:"Giải tán tổ chức đảng: quyết định cuối cùng vấn là cấp uỷ cấp trên cách một cấp (giống câu 142). Nặng nhất., lên cách một cấp.",t:"m",q:"Khi giải tán một tổ chức đảng, cơ quan nào có thẩm quyền quyết định cuối cùng?",o:["Cấp uỷ cấp trên trực tiếp.","Cấp uỷ cấp trên cách một cấp.","Ban Thường vụ Tỉnh uỷ.","Ủy ban kiểm tra Trung ương."],c:1},{id:"vb04-169",s:"",cc:"Điều 37, khoản 1-3 -— Điều lệ Đảng.",gt:"Bà nội dung này đều thể hiện đúng quy định tại Điều 37 về kỷ luật tổ chức đảng.",mn:"Kỷ luật tổ chức đảng (Điều 37): cấp trên trực tiếp khiển trách/cảnh cáo, giải tán do cách một cấp, chỉ giải tán khi chống Đảng/vi phạm đặc biệt nghiêm trọng „ cảA, B, C đều đúng (D).",t:"m",q:"Khẳng định nào sau đây là dụng khi xử lý kỷ luật tổ chức đảng vi phạm?",o:["Cấp uỷ cấp trên trực tiếp quyết định khiển trách, cảnh cáo tổ chức đảng cấp dưới.","Kỷ luật giải tán do cấp uỷ cấp trên cách một cấp quyết định.","Chỉ giải tán khi tổ chức đó chống đường lối, chính sách của Đảng hoặc vi phạm đặc biệt nghiêm trọng nguyên tắc tổ chức.","GCaảA,B,C đều đúng."],c:3},{id:"vb04-170",s:"",cc:"Điều 39, khoản 2 -— Điều lệ Đảng.",gt:"Tổ chức đảng vi phạm phải kiểm điểm, tự nhận hình thức kỷ luật và báo cáo cấp uỷ cấp trên quyết định.",mn:'Tổ chức đảng vi phạm phải Kiểm điểm - Tự nhận hình thức kỷ luật - Báo cáo cấp trên quyết định. Nhớ chuỗi: "Kiểm - Nhận - Báo”.',t:"m",q:"Trong quá trình xem xét kỷ luật, tổ chức đảng vi phạm phải:",o:["Báo cáo lên Ban Tổ chức Trung ương.","Kiểm điểm, tự nhận hình thức kỷ luật và báo cáo lên cấp uỷ cấp trên quyết định.","Đề nghị Ủy ban Kiểm tra xem xét thấy.","Cho ý kiến chỉ đạo của Ban Bí thư."],c:1},{id:"vb04-171",s:"",cc:"Điều 39, khoản 7 = Điều lệ Đảng.",gt:"Trong vòng 1 tháng (30 ngày) kể từ ngày nhận quyết định, tổ chức đảng hoặc đảng viên có quyền khiếu nại lên cấp trên.",mn:"Khiếu nại kỷ luật trong 30 ngày (1 tháng) kể từ ngày nhận quyết định. Nhớ: một tháng = 30 ngày.",t:"m",q:"Khi tổ chức đảng hoặc đảng viên không đồng ý với quyết định kỷ luật, thời hạn khiếu nại là bao lâu kể từ ngày nhận quyết định?",o:["7ngày.","15 ngày. ¬","30 ngày.","45ngày."],c:2},{id:"vb04-172",s:"",cc:"Điều 39, khoản 8 — Điều lệ Đảng.",gt:"Thời hạn giải quyết: tối đa 3 tháng với cấp tỉnh, cấp xã; 6 tháng với cấp Trung ương. L- Cập nhật: theo mô hình tổ chức đảng 2 cấp (QĐ 20-QĐ/TW năm 2026), cấp địa phương gồm cấp tỉnh và cấp xã (xã, phường, đặc khu), không còn cấp huyện.",mn:'Giải quyết khiếu nại: 3 tháng cấp tỉnh/cấp xã, 6 tháng cấp Trung ương. Nhớ: "tinh/xã 3 - Trung ương gấp đôi = 6".',t:"m",q:"Cấp uỷ hoặc Ủy ban kiểm tra có thẩm quyền phải giải quyết khiếu nại kỷ luật trong thời hạn tối đa bao lâu?",o:["1 tháng đối với cấp xã; 3 tháng đối với cấp Trung ương.","3 tháng đối với cấp tỉnh, cấp xã; 6 tháng đối với cấp Trung ương.","6 tháng đối với tất cả các cấp.","Không quá 90 ngày."],c:1},{id:"vb04-173",s:"",cc:"Điều 40, khoản 3 — Điều lệ Đảng.",gt:"Đảng viên bị cách chức không bị đình chỉ sinh hoạt đảng: chỉ bị hạn chế quyền bổ nhiệm, bầu cử trong 1 năm.",mn:"Cách chức KHÔNG tự động đình chỉ sinh hoạt đảng _›, khẳng định SAI là C. Chỉ bị hạn chế bổ nhiệm/bầu cử trong 1 năm, vẫn sinh hoạt đảng bình thường. [rac nghiệm Điều lệ Đảng | Trang b2 Chương IX: ĐẢNG LÃNH ĐẠO NHÀ NƯỚC, MẶT TRẬN TỔ QUỐC VÀ ĐOÀN THỂ CHÍNH TRỊ - XÃ HỘI",t:"m",q:"Khẳng định nào sau đây là sai về hậu quả của hình thức kỷ luật “cách chức”?",o:["Đảng viên bị cách chức không được bầu vào cấp uỷ trong vòng 1 năm.","Không được bổ nhiệm chức vụ tương đương hoặc cao hơn trong vòng 1 năm.","Tự động bị đình chỉ sinh hoạt đảng.","Có thể được xem xét phục hồi chức vụ sau thời gian thử thách."],c:2},{id:"vb04-174",s:"",cc:"Điều 41, khoản 1 = Điều lệ Dụng.",gt:"Đảng lãnh đạo bằng Cương lĩnh, chiến lược, chính sách, chủ trương, cùng công tác tư tưởng, tổ chức, cán bộ, kiểm tra, giám sát.",mn:'Đảng lãnh đạo bằng Cương lĩnh, chiến lược, chính sách, chủ trương + 5 công tác: tư tưởng - tổ chức - cán bộ - kiểm tra - giám sát. Nhớ "Cưỡng - chiến — chính - chủ”.',t:"m",q:"Đảng lãnh đạo Nhà nước, Mặt trận Tổ quốc và đoàn thể chính trị - xã hội bằng phương thức nào?",o:["Cương lĩnh chính trị, chiến lược, chính sách, chủ trương; công tác tư tưởng, tổ chức, cán bộ, kiểm tra, giám sát.","Pháp luật và nghị định của Chính phủ.","Hệ thống quy chế nội bộ.","Các chương trình hành động của Chính phủ."],c:0},{id:"vb04-175",s:"",cc:"Điều 4l, khoản 2 = Điều lệ Động.",gt:"Đảng thống nhất lãnh đạo công tác cán bộ, đồng thời phát huy trách nhiệm của tổ chức và người đứng đầu. ^:.ixt",mn:'Thống nhất lãnh đạo cán bộ nhưng "đi đôi" với phát huy trách nhiệm người đứng đầu trong hệ thống chính trị. Chốt cụm người đứng đầu.',t:"m",q:"Đảng thống nhất lãnh đạo công tác cán bộ và quản lý đội ngũ cán bộ đi đôi với:",o:["Việc ban hành nghị quyết công tác cán bộ.","Phát huy trách nhiệm của các tổ chức và người đứng đầu trong hệ thống chính trị.","Tăng cường vai trò của Ủy ban Kiểm tra Trung ương.","Giám sát công tác bầu cử và bổ nhiệm."],c:1},{id:"vb04-176",s:"",cc:"Điều 41, khoản 3 — Điều lệ Dụng.",gt:"Đảng giới thiệu cán bộ đủ tiêu chuẩn ứng cử hoặc bổ nhiệm vào các cơ quan trong hệ thống chính trị.",mn:"Giới thiệu cán bộ đủ tiêu chuẩn để ứng cử hoặc bổ nhiệm vào Nhà nước, Mặt trận, đoàn thể. Nhớ cặp ứng cử - bổ nhiệm.",t:"m",q:"Đảng giới thiệu cán bộ đủ tiêu chuẩn để làm gì?",o:["Ứng cử hoặc bổ nhiệm vào cơ quan Nhà nước, Mặt trận Tổ quốc, đoàn thể chính trị - xã hội.","Tham gia hội nghị cấp uỷ.","Bổ sung vào cơ quan đảng ở địa phương.","Làm công tác kiểm tra, giám sát. lưác nghiệm Điều lệ Đảng Trang hồ"],c:0},{id:"vb04-177",s:"",cc:"Điều 4Ì, khoản 4 - Điều lệ Dụng.",gt:"Đảng viên phải chấp hành nghị quyết, chỉ thị của Đảng, cụ thể hóa trong văn bản của cơ quan Nhà nước, Mặt trận và đoàn thể.",mn:"Đảng viên phải chấp hành nghị quyết, chỉ thị rồi cụ thể hóa thành văn bản pháp luật. Không phải chỉ theo pháp luật - phải theo Đảng trước.",t:"m",q:"Tổ chức đảng và đảng viên công tác trong cơ quan Nhà nước, Mặt trận Tổ quốc phải:",o:["Chỉ tuân thủ pháp luật Nhà nước.","Chấp hành nghị quyết, chỉ thị của Đảng và cử thể hóa thành văn bản pháp luật, chủ trương của đoàn thể.","Báo cáo định kỳ cho cơ quan hành chính.","Thực hiện độc lập, không phù thuộc tổ chức đảng."],c:1},{id:"vb04-178",s:"",cc:"Mục I0.4.2 (Điều 42, 43) — Quy định số 20-Q33371W về thi hành Điều lệ Đảng.",gt:"Từ năm 2025, mô hình đảng đoàn, ban cán sự đảng đã kết thúc hoạt động; thay bằng các đảng bộ trực thuộc Trung ương (Đảng bộ Quốc hội, Chính phủ, Mặt trận Tổ quốc và các đoàn thể Trung ương).",mn:"Nhớ: hết đảng đoàn/ban cán sự -. nay là ĐẢNG BỘ (Quốc hội, Chính phủ, MTTQ). lưác nghiện) Điều lệ Đảng Trang b4",t:"m",q:"Theo mô hình tổ chức đảng hiện hành (từ năm 2025), trong cơ quan Nhà nước, Mặt trận Tổ quốc và các đoàn thể ở Trung ương, Đảng lãnh đạo thông qua tổ chức nào?",o:["Đảng đoàn và ban cán sự đảng","Các đảng bộ (Đảng bộ Quốc hội, Đảng bộ Chính phủ, Đảng bộ Mặt trận Tổ quốc và các đoàn thể Trung ương)","Ban chỉ đạo Trung ương","Tổ công tác của Bộ Chính trị"],c:1},{id:"vb04-179",s:"",cc:"Mục 10.4.2, Tiết a — Quy định số 20-Qb⁄T W.",gt:"Các đảng bộ ở Trung ương (Quốc hội, Chính phủ, Mặt trận Tổ quốc, các đoàn thể Trung ương) trực thuộc Ban Chấp hành Trung ương Đảng.",mn:"Đảng bộ cấp cao nhất thì gắn thắng với Ban Chấp hành Trung ương.",t:"m",q:"Đảng bộ Quốc hội, Đảng bộ Chính phủ, Đảng bộ Mặt trận Tổ quốc và các đoàn thể Trung ương trực thuộc cơ quan nào?",o:["Bộ Chính trị","Ban Bí thư","Ban Chấp hành Trung ương Đảng","Ban Tổ chức Trung ương"],c:2},{id:"vb04-180",s:"",cc:"Mục 10.4.2, Tiết a (Quy định số 20-Q)Ð⁄IW.",gt:"Bộ Chính trị quyết định thành lập và quyết định chức năng, nhiệm vụ, tổ chức bộ máy của các đảng bộ này.",mn:"Thành lập đảng bộ TW = việc của Bộ Chính trị.",t:"m",q:"Cơ quan nào có thẩm quyền quyết định thành lập Đảng bộ Quốc hội, Đảng bộ Chính phủ, Đảng bộ Mặt trận Tổ quốc và các đoàn thể Trung ương?",o:["Ban Chấp hành Trung ương","Ban Bí thư","Ban Tổ chức Trung ương","Bộ Chính trị"],c:3},{id:"vb04-181",s:"",cc:"Mục 10.4.2, Tiết b - (Quy định số 20-QQD/TW.",gt:"Đảng bộ các cơ quan Đảng tỉnh và đảng bộ Ủy ban nhân dân tỉnh, thành phố trực thuộc cấp uỷ cấp tỉnh; cấp uỷ cấp tỉnh quyết định thành lập.",mn:"Đảng bộ ở tỉnh thì thuộc cấp uỷ cấp tỉnh.",t:"m",q:"Ở cấp tỉnh, đảng bộ các cơ quan Đảng tỉnh và đảng bộ Ủy ban nhân dân tỉnh, thành phố trực thuộc cơ quan nào?",o:["Cấp uỷ cấp tỉnh (tỉnh uỷ, thành uỷ)","Ban Tổ chức Trung ương","Bộ Chính trị","Đảng bộ Chính phủ"],c:0},{id:"vb04-182",s:"",cc:"Mục 10.4.2, Tiết b — Quy định số 20-(ÀĐ⁄TW.",gt:"Cấp uỷ cấp tỉnh quyết định thành lập; ban thường vụ tỉnh uỷ, thành uỷ quyết định chức năng, nhiệm vụ, tổ chức bộ máy của các đảng bộ này.",mn:"Cấp uỷ lập - ban thường vụ quyết định chức năng, nhiệm vụ.",t:"m",q:"Ban thường vụ tỉnh uỷ, thành uỷ có thẩm quyền gì đối với đảng bộ các cơ quan Đảng tỉnh và đảng bộ Ủy ban nhân dân tỉnh?",o:["Trực tiếp bầu bí thư các đảng bộ đó","Quyết định chức năng, nhiệm vụ, tổ chức bộ máy","Chỉ định toàn bộ đảng viên","Không có thẩm quyền gì"],c:1},{id:"vb04-183",s:"",cc:"Mục 10.4.2, Tiết a (Quy định số 20-Q)Ð⁄IW.",gt:"Ban Thường vụ Đảng uỷ Quốc hội quyết định thành lập, quyết định chức năng, nhiệm vụ và trực tiếp lãnh đạo tổ đảng ở đoàn đại biểu Quốc hội (hoạt động tại các kỳ họp).",mn:"Tổ đảng đoàn ĐBQH. › Ban Thường vụ Đảng uỷ Quốc hội lo.",t:"m",q:"Tổ đảng ở đoàn đại biểu Quốc hội (hoạt động tại các kỳ họp Quốc hội) do cơ quan nào quyết định thành lập và trực tiếp lãnh đạo?",o:["Ủy ban Thường vụ Quốc hội","Bộ Chính trị","Ban Thường vụ Đảng uỷ Quốc hội","Ban Tổ chức Trung ương"],c:2},{id:"vb04-184",s:"",cc:"Mục 17 — Quy định số 20-QD/TW. [rác nghiệm Điều lệ Đảng ï- Trang D6",gt:"Thí điểm Bộ Chính trị chỉ định ban chấp hành, ban thường vụ, bí thư, phó bí thư, Ủy ban kiểm tra... của đảng uỷ các cơ quan Đảng Trung ương, Chính phủ, Quốc hội, Mặt trận Tổ quốc và các đoàn thể Trung ương.",mn:"Cấp Trung ương thì Bộ Chính trị chỉ định (không bầu).",t:"m",q:"Theo Quy định số 20-QĐÐ/TW, đang thực hiện thí điểm Bộ Chính trị chỉ định ban chấp hành, ban thường vụ, bí thư, phó bí thư của đảng uỷ nào?",o:["Đảng uỷ xã, phường, đặc khu","Chi bộ trực thuộc","Đảng uỷ cấp cơ sở","Các cơ quan Đảng Trung ương; Chính phủ; Quốc hội; Mặt trận Tổ quốc, các đoàn thể Trung ương"],c:3},{id:"vb04-185",s:"",cc:"Mục I0.4.2 (Điều 4l, 42, 43) -- (Quy định số 2U-QbD⁄] W.",gt:"Mô hình đảng bộ nhằm bảo đảm Đảng lãnh đạo trực tiếp, toàn diện đối với cơ quan Nhà nước, Mặt trận Tổ quốc và đoàn thể tương ứng.",mn:"Đảng bộ lập ra để lãnh đạo trực tiếp, toàn diện.",t:"m",q:"Việc thành lập Đảng bộ Quốc hội, Đảng bộ Chính phủ nhằm mục đích chủ yếu nào?",o:["Thay Ủy ban Thường vụ Quốc hội điều hành công việc","Đế Đảng lãnh đạo trực tiếp, toàn diện đối với cơ quan Nhà nước tương ứng","Thay thế Quốc hội, Chính phủ","Chí để làm công tác thi đua, khen thưởng"],c:1},{id:"vb04-186",s:"",cc:"Mục 18.12 - (Quy định số 20-QÐ7IW.",gt:"Các đảng uỷ trực thuộc Trung ương được lập 4 cơ quan tham mưu, giúp việc: Văn phòng, ban tổ chức, cơ quan ủy ban kiểm tra, ban tuyên giao và dân vấn.",mn:"4 cơ quan: Văn phòng - Tổ chức - UBKT - Tuyên giáo & Dân vấn.",t:"m",q:"Cơ quan chuyên trách tham mưu, giúp việc của các đảng uỷ trực thuộc Trung ương (như Đảng bộ Chính phủ, Đảng bộ Quốc hội) gồm những cơ quan nào?",o:["Chỉ có Văn phòng","Văn phòng, ban tổ chức, cơ quan ủy ban kiểm tra, ban tuyên giao và dân vận","Chỉ có bản tổ chức và văn phòng","Không có cơ quan tham mưu"],c:1},{id:"vb04-187",s:"",cc:"Mục 10.4.2 (Điều 42, 43) - Quy định số 20-QĐÐ/TW.",gt:"Điểm mới: kết thúc mô hình đảng đoàn, ban cán sự đảng, chuyển sang mô hình đảng bộ (đảng bộ Quốc hội, Chính phủ, Mặt trận Tổ quốc...) để tăng cường sự lãnh đạo trực tiếp của Đảng.",mn:"Trước: đảng đoàn/ban cán sự -— Này: ĐẢNG BỘ.",t:"m",q:"Điểm mới cần bản trong tổ chức đảng ở cơ quan Nhà nước, Mặt trận Tổ quốc và đoàn thể từ năm 2025 so với trước đây là gì?",o:["Kết thúc mô hình đảng đoàn, ban cán sự đảng; thay bằng mô hình đảng bộ","Giữ nguyên đảng đoàn, ban cán sự đảng như cũ","Chỉ đổi tên gọi, giữ nguyên chức năng","Bỏ hoàn toàn tổ chức đảng trong cơ quan Nhà nước lưác nghiện Điều lệ Đảng Trang 6Ó"],c:0},{id:"vb04-188",s:"",cc:"Mục 10.1 (Khoản 1, Điều 10) - Quy định số 20-(ÀÐ⁄] W.",gt:"Hệ thống tổ chức của Đảng nay gồm 3 cấp: cấp xã (xã, phường, đặc khu) - cấp tỉnh, thành phố - Trung ương; không còn cấp huyện.",mn:"Nhớ 3 cấp: Xã - Tỉnh - Trung ương (bộ huyện). Chương X: ĐẢNG LÃNH ĐẠO ĐOÀN THANH NIÊN CỘNG SẢN HỒ CHÍ MINH",t:"m",q:"Hệ thống tổ chức của Đảng hiện này được lập tương ứng với hệ thống tổ chức hành chính Nhà nước, gồm các cấp nào?",o:["Bốn cấp: Trung ương - tỉnh - huyện - xã","Ba cấp: cấp xã (xã, phường, đặc khu) - cấp tỉnh, thành phố - Trung ương","Hai cấp: Trung ương và cơ sở","Năm cấp hành chính"],c:1},{id:"vb04-189",s:"",cc:"Điều 44, khoản 1 — Điều lệ Đảng Cộng sản Việt Nam (Đại hội XI, 2011).",gt:"Đoàn Thanh niên Cộng sản Hồ Chí Minh là đội dự bị tin cậy của Đảng, thường xuyên bổ sung lực lượng trẻ cho Đảng.",mn:"Đoàn = đội dự bị tin cậy của Đảng, thường xuyên bổ sung lực lượng trẻ cho Đảng.",t:"m",q:"Đoàn Thanh niên Cộng sản Hồ Chí Minh được xác định là gì trong mối quan hệ với Đảng Cộng sản Việt Nam?",o:["Tổ chức chính trị - xã hội độc lập với Đảng.","Đội dự bị tin cậy của Đảng.","Lực lượng giám sát hoạt động của Đảng.","Cơ quan tuyên truyền của Nhà nước."],c:1},{id:"vb04-190",s:"",cc:"Điều 44, khoản 1 -— Điều lệ Đảng.",gt:"Đoàn Thanh niên Cộng sản Hồ Chí Minh phụ trách Đội Thiếu niên Tiền phong Hồ Chí Minh.",mn:"Đoàn phụ trách Đội Thiếu niên Tiền phong Hồ Chí Minh.",t:"m",q:"Đoàn Thanh niên Cộng sản Hồ Chí Minh có nhiệm vụ phụ trách tổ chức nào của thiếu niên?",o:["Hội Liên hiệp Thanh niên Việt Nam.","Hội Sinh viên Việt Nam.","Đội Thiếu niên Tiền phong Hồ Chí Minh.","Hội đồng Đối Trung ương."],c:2},{id:"vb04-191",s:"",cc:"Điều 44, khoản 2 Điều lộ Đảng.",gt:"Cấp uỷ đảng lãnh đạo trực tiếp tổ chức đoàn cùng cấp về phương hướng, nhiệm vụ, tư tưởng, tổ chức, cán bộ.",mn:"Cấp uỷ lãnh đạo Đoàn theo 5 mặt: Phương hướng - Nhiệm vụ — Tư tưởng — Tổ chức - Cán bộ (P-N-T-1-C).",t:"m",q:"Cấp uỷ đảng lãnh đạo trực tiếp tổ chức đoàn cùng cấp về những mặt nào?",o:["Phương hướng, nhiệm vụ, tư tưởng, tổ chức, cán bộ.","Chính sách, ngân sách, nhân sự, thi đua.","Kế hoạch công tác và hoạt động tài chính.","Đường lối, nghị quyết và công tác kiểm tra."],c:0},{id:"vb04-192",s:"",cc:"Điều 44, khoản 1 — Điều lệ Đảng.",gt:"Đoạn vừa là lực lượng nòng cốt, vừa là trường học XHCN và đại diện quyền lợi thanh niên. ¬",mn:"Vai trò Đoàn gồm cả 3: nòng cốt phong trào thanh niên + trường học XHƠN + đại diện quyền lợi thanh niên = chọn “đều đúng”.",t:"m",q:"Khẳng định nào sau đây thể hiện đúng vai trò của Đoàn Thanh niên Cộng sản Hồ Chí Minh?",o:["Là lực lượng nòng cốt trong phong trào thanh niên.","Là trường học xã hội chủ nghĩa.","Là tổ chức đại diện quyền lợi của thanh niên.","Cả A,B,C đều đúng."],c:3},{id:"vb04-193",s:"",cc:"Điều 45 — Điều lộ Đảng Cộng sản Việt Nam.",gt:"Đảng viên còn trong độ tuổi đoàn phải sinh hoạt và công tác trong tổ chức Đoàn.",mn:"Đảng viên còn trong độ tuổi đoàn.. bắt buộc sinh hoạt và công tác trung Đoàn.",t:"m",q:"Đảng viên còn trong độ tuổi đoàn có trách nhiệm gì?",o:["Hướng dẫn đoàn viên sinh hoạt Đoàn.","Chỉ tham gia hoạt động khi có phân công.","Phải sinh hoạt và công tác trong tổ chức đoàn.","Được miễn sinh hoạt đoàn nếu là cán bộ lãnh đạo."],c:2},{id:"vb04-194",s:"",cc:"Điều 44, khoản 1 - Điều lệ Đảng.",gt:"Đoàn không lãnh đạo các tổ chức chính trị - xã hội, mà chỉ là đội dự bị, lực lượng nòng cốt phong trào thanh niên và phụ trách Đội TNTP.",mn:"3 chủ D đúng › “Dự bị - Đầu tàu phong trào - Đội TNTP”. & ] Nội dung “lãnh đạo” chỉ thuộc về Đảng, không phải Đoàn.",t:"m",q:"Nhận định nào sau đây không đúng về vai trò của Đoàn Thanh niên Cộng sản Hồ Chí Minh?",o:["Đoàn là đội dự bị tin cậy của Đảng.","Đoàn là lực lượng nòng cốt trong phong trào thanh niên.","Đoàn lãnh đạo trực tiếp các tổ chức chính trị - xã hội ở cơ sử.","Đoàn phụ trách Đội Thiếu niên Tiền phong Hồ Chí Minh."],c:2},{id:"vb04-195",s:"",cc:"Điều 44, khoản 2 — Điều lệ Đảng. lưác nghiện) Điều lệ Đảng Trang C0",gt:"Cấp uỷ lãnh đạo trực tiếp, toàn diện Đoàn theo 5 mặt: phương hướng - nhiệm vụ — tư tưởng — tổ chức - cán bộ.",mn:"Mẹo “P-N-T-T-C? = Phương — Nhiệm — Tư — Tổ — Cán (5 chữ đầu).",t:"m",q:"Khẳng định nào sau đây là đúng về nhiệm vụ lãnh đạo của cấp uỷ đảng đối với Đoàn TNCS Hồ Chí Minh?",o:["Chỉ lãnh đạo về công tác cán bộ.","Lãnh đạo toàn diện: phương hướng, nhiệm vụ, tư tưởng, tổ chức, cán bộ.","Chỉ lãnh đạo về phương hướng và nhiệm vụ trọng tâm.","Giao quyền tự chủ hoàn toàn cho Đoàn."],c:1},{id:"vb04-196",s:"",cc:"Điều 44, khoản J.",gt:"Cụm từ chính xác trong Điều lệ: “Đội dự bị tin cậy của Đảng”.",mn:"Mẹo: “Thanh niên -, Dự bị đề lên Đảng”.",t:"m",q:"Đoàn Thanh niên Cộng sản Hồ Chí Minh là của Đảng, thường xuyên bổ sung lực lượng trẻ cho Đảng.",o:["Lực lượng nòng cốt","Trường học xã hội chủ nghĩa","Đội dự bị tin cậy","Tổ chức chính trị - xã hội độc lập"],c:2},{id:"vb04-197",s:"",cc:"Điều 45 ~— Điều lệ Đảng.",gt:"Điều lệ quy định bắt buộc, không có ngoại lệ: đảng viên còn tuổi đoàn phải sinh hoạt và công tác trong Đoàn.",mn:"“Tuổi đoàn mà con là Đảng ¬ bắt buộc vào Đoàn”.",t:"m",q:"Đảng viên còn trong độ tuổi đoàn không thực hiện nghĩa vụ sinh hoạt và công tác trong Đoàn thuộc trường hợp nào?",o:["Không có trường hợp nào, tất cả phải sinh hoạt Đoàn.","Được miễn nếu là cán bộ lãnh đạo cấp phòng trở lên.","Được miễn nếu đã công tác trong Đảng ủy.","Được miễn khi có lý do cá nhân đặc biệt."],c:0},{id:"vb04-198",s:"",cc:"Điều 44, khoản 1 — Điều lệ Đảng.",gt:"Đoàn thực hiện đồng thời 3 vai trò lớn: Dự bị của Đảng Nòng cốt phong trào thanh niên Trường học xã hội chủ nghĩa ¬",mn:"Mẹo 3 chữ N: Nòng cốt — Nối tiếp Đảng - Nơi rèn luyện (trường học XHCN). Chương XI: TÀI CHÍNH CỦA ĐẢNG",t:"m",q:"Chọn phương án đúng nhất:",o:["Đội dự bị tin cậy của Đảng.","Lực lượng nòng cốt trong phong trào thanh niên.","Trường học xã hội chủ nghĩa của thanh niên.","Cả A, B, C đều đúng."],c:3},{id:"vb04-199",s:"",cc:"Điều 46, khoản 1 — Điều lệ lông Cộng sản Việt Nam (Đại hội XI, 2011).",gt:"Tài chính của Đảng gồm đảng phí do đảng viên đóng, ngân sách nhà nước và các khoản thu khác.",mn:'Tài chính Đảng có 3 nguồn: đảng phí - ngân sách nhà nước - các khoản thu khác. Loại ngay đáp án có "tài trợ/viện trợ quốc tế".',t:"m",q:"Tài chính của Đảng bao gồm những nguồn nào sau đây?",o:["Đảng phí do đảng viên động và tài trợ của tổ chức quốc tế.","Ngân sách nhà nước, đảng phí đảng viên và các khoản thu khác.","Ngân sách nhà nước và các khoản viện trợ.","Tiền đóng góp tự nguyện của nhân dân."],c:1},{id:"vb04-200",s:"",cc:"Điều 46, khoản 2 Điều lệ Động.",gt:"Ban Chấp hành Trung ương quy định thống nhất nguyên tắc, chế độ quản lý tài chính, tài sản và mức đóng đảng phí.",mn:"Quy định thống nhất nguyên tắc, chế độ tài chính và mức đóng đảng phí là Ban Chấp hành Trung ương (cấp cao nhất mới quy định thống nhất).",t:"m",q:"Cơ quan nào quy định thống nhất nguyên tắc, chế độ quản lý tài chính, tài sản và mức đóng đảng phí của đảng viên?",o:["Bộ Chính trị.","Ban Bí thư.","Ban Tổ chức Trung ương.","Ban Chấp hành Trung ương."],c:3},{id:"vb04-201",s:"",cc:"Điều 46, khoản 3 - Điều lệ Đảng. lưác nghiện) Điều lệ Đảng",gt:"Hằng năm, cấp uỷ nghe báo cáo và quyết định nhiệm vụ tài chính của cấp mình.",mn:"Hằng năm cấp uỷ nghe báo cáo và quyết định nhiệm vụ tài chính của cấp mình. Chương XII: CHẤP HÀNH ĐIỀU LỆ ĐẢNG",t:"m",q:"Hằng năm, cấp uỷ các cấp có trách nhiệm gì trong công tác tài chính của Đảng?",o:["Kiểm tra thu - chi đảng phí.","Nghe báo cáo và quyết định nhiệm vụ tài chính của cấp mình.","Phân bổ ngân sách cho đoàn thể trực thuộc.","Đề xuất mức đóng đảng phí mới."],c:1},{id:"vb04-202",s:"",cc:"Điều 47 - Điều lệ Đảng Cộng sản Việt Nam (Đại hội XI, 2011).",gt:"Cả tổ chức đảng và đảng viên đều phải chấp hành nghiêm chỉnh Điều lệ Đảng.",mn:'Chấp hành Điều lệ là cá tổ chức đảng và toàn thể đảng viên - không phải "chỉ” một bên nào.',t:"m",q:"Ai có trách nhiệm chấp hành nghiêm chỉnh Điều lệ Đảng?",o:["Chỉ đảng viên chính thức.","Chỉ tổ chức đảng các cấp.","Tổ chức đảng và toàn thể đảng viên.","Cán bộ, công chức nhà nước."],c:2},{id:"vb04-203",s:"",cc:"Điều 48 — Điều lệ Đảng.",gt:"Chỉ Đại hội đại biểu toàn quốc của Đảng mới có quyền sửa đổi Điều lệ Đảng.",mn:"Chỉ Đại hội đại biểu toàn quốc mới có quyền sửa đổi Điều lệ Đảng (cấp ra Điều lệ mỗi sửa được).",t:"m",q:"Cơ quan nào có quyền sửa đổi Điều lệ Đảng?",o:["Ban Chấp hành Trung ương.","Bộ Chính trị.","Ban Bí thư.","Đại hội đại biểu toàn quốc."],c:3}];export{n as default};
